/* 臨床心理 院試ノート：用語説明（独自作成。build.py で生成） */
window.SI_FIELDS = [{"id":"rinsho","name":"臨床心理学・心理療法","short":"臨床","d":"主要な心理療法の理論と技法。人間観・治療目標・治療関係の違いを押さえる。日本で生まれた心理療法も含む。"},{"id":"seishin","name":"精神分析・力動論","short":"精神分析","d":"フロイトから対象関係論・自己心理学・現代の精神分析まで。日本の精神分析（甘え・阿闍世）や治療構造論も含む。"},{"id":"jung","name":"分析心理学（ユング）","short":"ユング","d":"集合的無意識と元型、個性化、夢と象徴の理解。昔話・神話の理解や、箱庭など日本での展開も含む。"},{"id":"trauma","name":"トラウマ・被害者支援・危機介入","short":"トラウマ","d":"PTSDと複雑性PTSD、トラウマに焦点を当てた治療、被害者支援と二次被害、支援者自身のケア。"},{"id":"iryo","name":"精神医学・医療・老年","short":"医療","d":"診断分類と主な精神疾患、心身医学、小児医療・緩和ケア・認知症の人への支援、医療の中での連携。"},{"id":"assess","name":"心理アセスメント","short":"アセスメント","d":"投映法・質問紙法・知能検査・発達検査、テスト・バッテリー、見立てと所見の伝え方。"},{"id":"hattatsu","name":"発達・家族・教育","short":"発達","d":"愛着、生涯発達、子どもと家族の臨床、学校臨床と関連する法制度。"},{"id":"kiso","name":"基礎心理学","short":"基礎","d":"学習・記憶・感情・動機づけ・社会心理学など、臨床の土台になる基礎研究。"},{"id":"kenkyu","name":"研究法・統計","short":"研究法","d":"信頼性と妥当性、研究デザイン、統計的推論、質的研究、研究倫理。研究計画書と口述試験の質疑にも直結する。"},{"id":"rinri","name":"倫理・制度・コミュニティ","short":"制度","d":"職業倫理と法制度、資格、コミュニティ心理学、予防とコンサルテーション、多職種連携。"}];
window.SI_TERMS = (window.SI_TERMS || []).concat([{"id":"rogers-cct","t":"来談者中心療法","en":"client-centered therapy","f":"rinsho","a":"ロジャーズ（Rogers, C. R.）が1940年代に非指示的療法として提唱し、のちにパーソン・センタード・アプローチへと発展した心理療法。人は本来、成長し自己を実現しようとする実現傾向をもつという人間観に立つ。治療者が自己一致・無条件の肯定的配慮・共感的理解を備えた関係を提供すれば、クライエントは自己概念と経験のずれを自ら修正し、より柔軟な自己を生きられるようになると考える。技法よりも、治療者の態度と関係そのものを重視する点に特徴がある。","k":["ロジャーズ/Rogers","実現傾向","自己一致","無条件の肯定的配慮","共感的理解","自己概念"],"p":"「非指示的」から「来談者中心」へと呼び名が変わった経緯（技法から態度へ）にふれると厚みが出る。精神分析（解釈・転移）や行動療法（技法・学習）との対比で問われやすい。"},{"id":"rogers-cond","t":"治療的人格変化の必要十分条件","en":"necessary and sufficient conditions","f":"rinsho","a":"ロジャーズが1957年に示した、建設的な人格変化が起こるための6つの条件。①二人の人が心理的な接触をもっている、②クライエントは不一致の状態にあり、傷つきやすく不安である、③治療者は関係の中で一致し統合されている、④治療者はクライエントに無条件の肯定的配慮を経験している、⑤治療者は共感的理解を経験し、それを伝えようとしている、⑥それらが最低限クライエントに伝わっている。③④⑤は中核3条件と呼ばれる。","k":["1957","心理的な接触/心理的接触","不一致","無条件の肯定的配慮","共感的理解","伝わ"],"p":"「3条件」だけを書く答案が多い。6条件全体と、とくに⑥「伝わっていること」の意味（治療者の内面だけでは足りない）まで書けると差がつく。"},{"id":"congruence","t":"自己一致（純粋性）","en":"congruence / genuineness","f":"rinsho","a":"ロジャーズの中核条件の一つで、純粋性とも呼ばれる。治療者が関係の中で体験していることと、意識していること、表明していることが一致している状態をいう。治療者が専門家という役割や仮面の陰に隠れず、自分の内に生じる感情に開かれていることを指し、思ったことを何でも口にすることとは異なる。治療者の自己一致は、クライエントが自分の体験に開かれていくためのモデルとなり、無条件の肯定的配慮や共感が本物として伝わるための土台にもなる。","k":["ロジャーズ","純粋性","体験","一致","仮面/役割"],"p":"「何でも正直に言う」ことと区別できるかが問われる。共感・受容が「技法」として演じられると不一致になる、という論点も使える。"},{"id":"behavior-therapy","t":"行動療法","en":"behavior therapy","f":"rinsho","a":"学習理論にもとづき、不適応な行動を、誤って学習された、あるいは適切な行動が未学習である結果ととらえ、学習の原理を用いて行動の変容をめざす心理療法の総称。レスポンデント条件づけにもとづく系統的脱感作法やエクスポージャー法、オペラント条件づけにもとづく強化、シェイピング、トークン・エコノミーなどがある。1950年代にウォルピやアイゼンクらにより体系化された。観察可能な行動と効果の測定を重視し、のちの認知行動療法の基盤となった。","k":["学習理論","系統的脱感作/エクスポージャー","オペラント","ウォルピ/Wolpe","認知行動療法"],"p":"「内面を扱わない」と単純化せず、問題を具体的に定義し、効果を測って検証する姿勢が臨床心理学の科学化に果たした役割にふれるとよい。"},{"id":"sd","t":"系統的脱感作法","en":"systematic desensitization","f":"rinsho","a":"ウォルピ（Wolpe, J.）が逆制止の原理にもとづいて考案した行動療法の技法。まず筋弛緩法などでリラックス反応を身につけ、次に不安を引き起こす場面を弱いものから強いものへ並べた不安階層表を作る。リラックスした状態で、階層の低い場面から順にイメージし、不安が生じなくなったら次の段階へ進む。不安と両立しない反応を対にして提示することで、不安反応を段階的に弱めていく方法であり、恐怖症などに用いられる。","k":["ウォルピ/Wolpe","逆制止","不安階層表","筋弛緩/リラックス","恐怖症"],"p":"現在はリラクセーションを必須としないエクスポージャー法が主流であることも添えると、知識の更新ができていることを示せる。"},{"id":"cbt","t":"認知行動療法","en":"cognitive behavioral therapy","f":"rinsho","a":"感情や行動は、出来事そのものよりも、その受け止め方（認知）に影響されるという考えに立ち、認知と行動の両面に働きかけて問題の改善をはかる心理療法の総称。ベックの認知療法、エリスの論理療法、行動療法の技法が統合されて発展した。治療者とクライエントが協力して仮説を検証していく協働的経験主義のもと、問題を具体的に定式化し、セルフモニタリング、認知再構成、行動活性化、エクスポージャーなどを用いる。構造化されており、ホームワークを重視する。","k":["認知","ベック/Beck","協働的経験主義","認知再構成","ホームワーク"],"p":"「第三世代」（マインドフルネス、ACT、DBT）との違い（認知の内容を変えるか、認知との関わり方を変えるか）を整理しておくと比較問題に対応しやすい。"},{"id":"auto-thought","t":"自動思考","en":"automatic thoughts","f":"rinsho","a":"ベック（Beck, A. T.）の認知療法の中心的な概念で、ある状況で意図せずに瞬間的に浮かぶ考えやイメージをいう。本人には事実そのものとして体験されやすく、抑うつや不安などの感情を直接に左右する。自動思考の背後には、より持続的な信念である中核信念（スキーマ）があり、それが「全か無か思考」「破局視」などの認知の歪みを生むと考えられる。治療では思考記録表などを用いて自動思考に気づき、その根拠と反証を検討して、より柔軟な考え方を探る。","k":["ベック/Beck","瞬間","スキーマ/中核信念","認知の歪み","思考記録"],"p":"自動思考 → 媒介信念 → 中核信念という階層構造まで書けると正確。うつ病の「認知の3徴（自己・世界・将来）」もあわせて覚える。"},{"id":"rebt","t":"論理療法（REBT）","en":"rational emotive behavior therapy","f":"rinsho","a":"エリス（Ellis, A.）が1950年代に創始した心理療法。出来事（A）が直接に感情や行動の結果（C）を生むのではなく、その間にある信念（B）が結果を決めるとするABC理論を中核とする。とくに「〜ねばならない」という絶対的で非合理な信念（イラショナル・ビリーフ）が苦悩を生むと考え、それに論駁（D）を加えて、より合理的で柔軟な信念へと置き換え、効果（E）を得ることをめざす。ベックの認知療法と並ぶ、認知行動療法の源流の一つである。","k":["エリス/Ellis","ABC","イラショナル/非合理","論駁","ねばならない"],"p":"ベックの認知療法との違い（エリスはより直面的・説得的に論駁し、ベックは協働的に検証する）を一言添えると比較の視点が示せる。"},{"id":"mindfulness","t":"マインドフルネス","en":"mindfulness","f":"rinsho","a":"意図的に、今この瞬間の体験に、評価や判断を加えずに注意を向けること、またそのような心のあり方をいう。仏教の瞑想に由来し、カバットジン（Kabat-Zinn, J.）が慢性疼痛などをもつ人を対象に、マインドフルネス・ストレス低減法（MBSR）として体系化した。さらに、うつ病の再発予防を目的とするマインドフルネス認知療法（MBCT）が開発された。思考の内容を変えるのではなく、思考や感情との関わり方を変える点で、従来の認知療法とは異なる。","k":["今この瞬間","判断/評価","カバットジン/Kabat-Zinn","MBSR/ストレス低減法","MBCT/マインドフルネス認知療法","再発予防"],"p":"「リラクセーション法」と混同しないこと。体験を変えようとせず観察する、という点が要点。"},{"id":"act","t":"アクセプタンス＆コミットメント・セラピー（ACT）","en":"acceptance and commitment therapy","f":"rinsho","a":"ヘイズ（Hayes, S. C.）らが開発した、いわゆる第三世代の認知行動療法。言語と認知に関する関係フレーム理論を背景に、苦痛な思考や感情を取り除こうとする「体験の回避」が、かえって苦しみを深め、生活を狭めると考える。アクセプタンス、脱フュージョン、今この瞬間との接触、文脈としての自己、価値、コミットされた行為の6つのプロセスを通じて心理的柔軟性を高め、本人が大切にする価値に沿った行動を広げていくことをめざす。","k":["ヘイズ/Hayes","関係フレーム理論","体験の回避","脱フュージョン","心理的柔軟性","価値"],"p":"症状の除去ではなく「価値に沿った生活」を目標にする点が、精神分析やロジャーズの人間観とどう響き合い、どう違うかを論じる材料になる。"},{"id":"dbt","t":"弁証法的行動療法（DBT）","en":"dialectical behavior therapy","f":"rinsho","a":"リネハン（Linehan, M. M.）が、自殺行動を繰り返す境界性パーソナリティ障害の人のために開発した認知行動療法。感情調節の困難は、生物学的な脆弱性と、感情を否定される環境との相互作用で生じるとする生物社会理論に立つ。受容と変化という対立するものを統合する弁証法を基本の姿勢とし、個人療法、スキル・トレーニング（マインドフルネス、苦悩耐性、感情調節、対人関係保持）、電話コーチング、治療者のコンサルテーション・チームを組み合わせる。","k":["リネハン/Linehan","境界性パーソナリティ","生物社会理論","受容","弁証法","スキル"],"p":"「受容と変化の弁証法」は、ロジャーズの受容と行動療法の変化をどう両立させるかという臨床の根本問題への一つの答えとして論じられる。"},{"id":"family-therapy","t":"家族療法（システムズ・アプローチ）","en":"family therapy","f":"rinsho","a":"個人の症状や問題を、その人の内面だけでなく、家族というシステムの相互作用の中でとらえ、家族全体に働きかける心理療法。一般システム理論やサイバネティクスを背景に、原因と結果が互いに影響し合って循環する円環的因果律で問題をみる。症状を示す人をIP（患者とみなされた人）と呼び、症状が家族の均衡（ホメオスタシス）を保つ役割を担っていることもあると考える。構造派（ミニューチン）、戦略派、ミラノ派、多世代派（ボーエン）など多くの学派がある。","k":["システム","円環的因果律","IP/患者とみなされた","ホメオスタシス","ミニューチン/構造派"],"p":"直線的因果律（誰が悪いか）との対比が書ければ合格点。不登校や摂食障害の事例問題で「家族全体を見る視点」として使える。"},{"id":"sfbt","t":"解決志向ブリーフセラピー","en":"solution-focused brief therapy","f":"rinsho","a":"ド・シェイザー（de Shazer, S.）とインスー・キム・バーグ（Berg, I. K.）らが開発した短期療法。問題の原因を探ることよりも、クライエントがすでにもっている資源や、問題が起きていない、あるいは少しうまくいっている「例外」に注目し、望む未来（解決）を共に描くことを重視する。奇跡が起きて問題が解決した翌朝を想像してもらうミラクル・クエスチョン、状態を数値で表してもらうスケーリング・クエスチョン、コーピング・クエスチョン、コンプリメントなどの技法を用いる。","k":["ド・シェイザー/de Shazer","例外","資源/リソース","ミラクル・クエスチョン","スケーリング"],"p":"「クライエントこそが自分の専門家である」という人間観が要。原因追究型（精神分析など）との対比で問われやすい。"},{"id":"narrative","t":"ナラティヴ・セラピー","en":"narrative therapy","f":"rinsho","a":"ホワイト（White, M.）とエプストン（Epston, D.）が提唱した、社会構成主義にもとづく心理療法。人は自分の人生を物語として意味づけて生きており、問題に満ちた支配的な物語（ドミナント・ストーリー）に縛られて苦しんでいると考える。問題を人から切り離して語る「問題の外在化」や、その物語に合わない出来事（ユニークな結果）に光を当てることを通じて、本人が望む別の物語（オルタナティヴ・ストーリー）を共に紡ぎ直していく。専門家の知よりも本人の知を尊重する。","k":["ホワイト/White","社会構成主義","ドミナント・ストーリー/支配的な物語","外在化","オルタナティヴ/別の物語"],"p":"「問題が問題であって、人が問題なのではない」という考え方を一文で示すとよい。社会や文化の言説が個人の物語を規定するという政治的な視点も特徴。"},{"id":"play-therapy","t":"遊戯療法","en":"play therapy","f":"rinsho","a":"言語による表現が十分でない子どもを主な対象に、遊びを主な表現・交流の手段として行う心理療法。精神分析の流れではアンナ・フロイトやクラインが子どもの分析に遊びを取り入れた。アクスライン（Axline, V. M.）は来談者中心療法の考えにもとづき、温かい関係、ありのままの受容、許容的な雰囲気、感情の察知と反射、子どもの主導の尊重、必要な制限などからなる8つの基本原理を示した。遊びは感情の表出、体験の象徴的な再演と統合、関係の修復などの働きをもつ。","k":["子ども","遊び","アクスライン/Axline","8つの基本原理/8原則","制限","象徴"],"p":"「制限」がなぜ必要か（子どもと治療者の安全、現実との接点、治療関係の保護）を説明できると論述でも強い。"},{"id":"sandplay","t":"箱庭療法","en":"sandplay therapy","f":"rinsho","a":"内側を青く塗った一定の大きさの砂箱の中に、ミニチュアの玩具を自由に置いて作品をつくる心理療法。ローエンフェルト（Lowenfeld, M.）の世界技法をもとに、カルフ（Kalff, D. M.）がユング心理学の観点から発展させ、1965年に河合隼雄が日本に紹介した。治療者に見守られた「自由にして保護された空間」の中で、言葉にならない内的な世界が象徴的に表現される。作品を一つずつ解釈することよりも、表現が生まれる関係と、作品の継時的な変化を重視する。","k":["砂箱/砂","ローエンフェルト/Lowenfeld","カルフ/Kalff","河合隼雄","自由にして保護された空間"],"p":"日本で広く受け入れられた理由（非言語的表現、日本の箱庭や盆景の文化との親和性）を論じさせる出題もありうる。"},{"id":"art-therapy","t":"芸術療法（表現療法）","en":"art therapy","f":"rinsho","a":"絵画、コラージュ、粘土、音楽、詩歌、ダンスなどの創作・表現活動を用いる心理療法の総称。言葉では表しにくい感情やイメージを非言語的に表現でき、表現すること自体のカタルシスや自己理解、さらに作品を介した治療者との交流が治療的に働くとされる。作品を無意識の表現として扱い言語化を重視する立場（ナウムバーグ）と、創作の過程そのものに治癒の力をみる立場（クレイマー）がある。日本では中井久夫の風景構成法など独自の展開もみられる。","k":["非言語","表現","ナウムバーグ/Naumburg","クレイマー/Kramer","作品"],"p":"「作品を診断に使う」ことと「表現の場を守る」ことの違いを意識して書く。侵襲性（表現が深い層を揺さぶること）への配慮にもふれられるとよい。"},{"id":"focusing","t":"フォーカシング","en":"focusing","f":"rinsho","a":"ジェンドリン（Gendlin, E. T.）が提唱した、からだで感じられる、まだ言葉にならない意味の感覚（フェルトセンス）に注意を向け、それにぴったりくる言葉やイメージを探していく方法。ロジャーズのもとでの研究で、心理療法がうまくいくクライエントは、面接の中で自分の体験に触れながら話す傾向があることが見いだされたことに始まる。体験過程理論にもとづき、フェルトセンスと言葉が響き合うときに起こる「フェルトシフト」が変化をもたらすとされる。","k":["ジェンドリン/Gendlin","フェルトセンス","体験過程","ロジャーズ","フェルトシフト"],"p":"来談者中心療法の「態度」を、クライエント側の「体験の仕方」の研究へと展開したもの、と位置づけると流れが説明できる。"},{"id":"mi","t":"動機づけ面接","en":"motivational interviewing","f":"rinsho","a":"ミラー（Miller, W. R.）とロルニック（Rollnick, S.）が開発した、変化に対する両価性（変わりたいが、変わりたくない）を解きほぐし、本人の内発的な動機を引き出す協働的な面接法。もとは飲酒問題の領域で発展した。開かれた質問、是認、聞き返し、要約（OARS）を基本のスキルとし、クライエントが自ら語る変化への言葉（チェンジトーク）を引き出して強める。説得や直面化は抵抗を強めるため避け、協働、受容、思いやり、喚起の精神を重視する。","k":["ミラー/Miller","両価性","チェンジトーク","聞き返し","協働"],"p":"来談者中心療法の態度を、目標に向けて方向づける（指向的）点が特徴。「来談者中心だが方向性をもつ」と説明すると違いが伝わる。"},{"id":"working-alliance","t":"作業同盟（治療同盟）","en":"working alliance","f":"rinsho","a":"治療者とクライエントが協力して治療に取り組む関係をいう。精神分析ではグリーンソン（Greenson, R.）が、転移とは区別される現実的な協力関係として論じた。ボーディン（Bordin, E. S.）は学派を超える概念として、目標についての合意、課題についての合意、情緒的な絆の3つの要素で定義した。同盟の質は、学派を問わず治療効果を予測することが多くの研究で示されている。同盟の亀裂と修復を扱うこと自体が治療的に重要であるとされる。","k":["協力","ボーディン/Bordin","目標","課題","絆","治療効果"],"p":"共通要因論とセットで出しやすい。「亀裂と修復」（サフラン）まで書けると現代的。"},{"id":"common-factors","t":"共通要因","en":"common factors","f":"rinsho","a":"学派や技法の違いを超えて、多くの心理療法に共通して治療効果をもたらす要因をいう。ローゼンツヴァイク（Rosenzweig, S.）は、異なる心理療法の効果に大差がないことを、『不思議の国のアリス』になぞらえて「ドードー鳥の評決」と表現した。ランバート（Lambert, M. J.）は効果に寄与する要因として、治療外の要因、治療関係、期待（プラセボ）、技法を挙げた。共感や作業同盟などの関係要因の重要性を示す一方、特定の問題に対する技法の効果を否定するものではない。","k":["学派","ローゼンツヴァイク/Rosenzweig","ドードー鳥","ランバート/Lambert","治療関係/作業同盟"],"p":"ランバートの割合（40/30/15/15）は実証値ではなく推定であることに注意。「技法は無意味」という極論に流れないこと。"},{"id":"group-therapy","t":"集団心理療法","en":"group psychotherapy","f":"rinsho","a":"複数のクライエントと治療者が集団で行う心理療法で、集団そのものの力動やメンバー間の相互作用を治療に活かす点に特徴がある。ヤーロム（Yalom, I. D.）は治療的因子として、希望をもたらすこと、普遍性（悩んでいるのは自分だけではないという体験）、情報の伝達、愛他主義、初期家族関係の修正的な繰り返し、対人学習、凝集性、カタルシス、実存的因子などを挙げた。精神分析的集団療法、心理劇、SST、自助グループなど多様な形態がある。","k":["相互作用","ヤーロム/Yalom","治療的因子","普遍性","凝集性"],"p":"個人療法にはない集団ならではの因子（普遍性・愛他主義・対人学習）を中心に書くと焦点が定まる。"},{"id":"morita","t":"森田療法","en":"Morita therapy","f":"rinsho","a":"精神科医の森田正馬が1919年ごろに創始した日本独自の精神療法で、主に神経症（森田は神経質と呼んだ）を対象とする。病気を恐れ、よりよく生きたいという欲望の強いヒポコンドリー性基調をもつ人が、症状に注意を向けるほど感覚が鋭くなり、注意がさらに固着する精神交互作用によって症状にとらわれると考える。症状を取り除こうとせず「あるがまま」に受け入れて目的本位に行動することをめざし、入院療法は絶対臥褥期から作業期を経て社会生活に向かう。","k":["森田正馬","神経質","ヒポコンドリー性基調","精神交互作用","あるがまま","絶対臥褥"],"p":"「症状を消そうとする努力が症状を強める」という逆説は、ACTの「体験の回避」と比較して論じることができる。"},{"id":"naikan","t":"内観療法","en":"Naikan therapy","f":"rinsho","a":"吉本伊信が、浄土真宗の一派に伝わる修行法「身調べ」を一般向けに改めて確立した日本独自の心理療法。集中内観では、約1週間、屏風で仕切った空間にこもり、母親をはじめとする身近な人に対する自分を、年代を区切って「していただいたこと」「して返したこと」「迷惑をかけたこと」の3つのテーマで具体的に想起する。面接者は定期的に訪れて報告を聴く。自己中心的な見方が揺らぎ、他者から支えられてきた事実への気づきが生じるとされ、依存症などにも応用されている。","k":["吉本伊信","身調べ","していただいたこと","して返したこと","迷惑をかけたこと"],"p":"「迷惑をかけられたこと」は問わない構造の意味（被害者的な見方からの転換）を説明できるとよい。虐待体験のある人への適用には慎重さが必要という論点もある。"},{"id":"logotherapy","t":"ロゴセラピー","en":"logotherapy","f":"rinsho","a":"精神科医フランクル（Frankl, V. E.）が創始した実存分析的な心理療法。強制収容所での体験を記した『夜と霧』でも知られる。人間の根源的な動機を、快楽への意志や権力への意志ではなく「意味への意志」に求めた。人はどのような状況にあっても、その状況に対する態度を選ぶ自由をもち、人生から問われている意味に応えていく存在だと考える。予期不安の悪循環を断つ逆説志向や、過剰な自己観察を外へ向けかえる反省除去などの技法がある。","k":["フランクル/Frankl","夜と霧","意味への意志","態度","逆説志向"],"p":"「快楽への意志＝フロイト、権力への意志＝アドラー」との対比で書くと位置づけが明確になる。"},{"id":"rinsho-no-chi","t":"臨床の知","en":"clinical knowledge","f":"rinsho","a":"哲学者の中村雄二郎が、近代科学の知と対比して提唱した知のあり方。近代科学は普遍性・論理性・客観性を原理とし、対象から距離をとって一般的な法則を求めるが、その結果、個々の具体的な事例や、関わる者自身の経験がこぼれ落ちる。これに対し臨床の知は、固有の場所や関係を重んじるコスモロジー、事物の多義性をとらえるシンボリズム、身体をそなえた相互的な行為としてのパフォーマンスを原理とする。一回性の出会いを扱う心理臨床の知を考えるうえで重要である。","k":["中村雄二郎","近代科学","普遍性","コスモロジー","シンボリズム","パフォーマンス"],"p":"「科学としての心理学と心理臨床」「事例研究の意義」などの思想系の論述で使える。エビデンスを否定する概念ではなく、補い合うものとして書く。"},{"id":"dohsa","t":"臨床動作法","en":"dohsa-hou","f":"rinsho","a":"成瀬悟策が、脳性まひのある人の動作の改善の試み（催眠研究に端を発する）から発展させた日本独自の心理療法。動作を、本人が意図し、そのための努力をして身体の運動が実現する心理的な過程ととらえる。援助者が課題となる動作（肩の上げ下げ、躯幹のひねりなど）を示し、本人が自分のからだに注意を向けて緊張を緩めたり動かしたりする体験を通して、自己のあり方や生活体験の変化をめざす。障害のある人だけでなく、ストレスやトラウマの支援、高齢者などにも用いられる。","k":["成瀬悟策","脳性まひ","意図","努力","動作"],"p":"「からだを通して心に働きかける」日本発の方法として、森田療法・内観療法と並べて整理しておく。"},{"id":"psychoeducation","t":"心理教育","en":"psychoeducation","f":"rinsho","a":"病気や障害、問題について正確な知識や情報を、本人や家族が受け入れやすい形で伝え、対処の方法を身につけて主体的に生活できるよう支援する方法。統合失調症の家族を対象とした研究から、家族の感情表出（EE）が高いと再発しやすいことが示され、家族心理教育が再発予防に有効とされたことが発展の契機となった。情報提供にとどまらず、困りごとへの対処技能の練習や、参加者どうしの支え合いを含む。うつ病、トラウマ、発達障害など幅広い領域で行われている。","k":["知識/情報","家族","感情表出/EE","再発","対処"],"p":"一方的な講義にならないこと（相手の受け止めを確かめながら伝える）が実践上の要点。トラウマ支援では「あなたの反応は異常な事態への正常な反応」と伝えることが重要。"},{"id":"unconscious","t":"無意識（局所論）","en":"the unconscious","f":"seishin","a":"フロイトは『夢解釈』（1900年）などで、心を意識・前意識・無意識の3つの領域に分ける局所論を示した。前意識は注意を向ければ意識化できる内容であり、無意識は抑圧によって意識から締め出され、通常は意識化できない欲動や願望、記憶からなる。無意識の内容は、夢、言い間違いなどの失錯行為、神経症の症状として、偽装された形で表れる。のちにフロイトは、自我にも無意識的な部分があることから、エス・自我・超自我からなる構造論を提唱した。","k":["フロイト/Freud","意識","前意識","抑圧","夢","構造論"],"p":"ユングの無意識（集合的無意識、創造的・目的論的）との比較は頻出。局所論→構造論へと理論が移った理由まで書ける準備を。"},{"id":"structural","t":"構造論（エス・自我・超自我）","en":"structural model","f":"seishin","a":"フロイトが1923年の『自我とエス』で示した心の構造のモデル。エス（イド）は快感原則に従う本能的欲動の貯蔵庫であり、超自我は親の禁止や理想が内在化した、良心と自我理想の働きである。自我は現実原則に従い、エスの欲動、超自我の要請、外界の現実の三者を調整する。自我がこの調整に失敗して不安が生じると、防衛機制が働く。局所論では説明しにくかった、自我や超自我にも無意識的な部分があるという理解を可能にした。","k":["1923","エス/イド","超自我","自我","現実原則","防衛"],"p":"「自我は3人の主人に仕える」という比喩で三者の関係を説明すると答案が締まる。"},{"id":"defense","t":"防衛機制","en":"defense mechanisms","f":"seishin","a":"自我が、受け入れがたい欲動や感情、それに伴う不安や罪悪感から自らを守るために、多くは無意識的に用いる心理的な働き。フロイトが論じ、娘のアンナ・フロイトが『自我と防衛機制』（1936年）で体系化した。抑圧、反動形成、投影、置き換え、合理化、知性化、隔離、打ち消し、退行、昇華などがある。防衛そのものは誰にでもある適応的な働きであり、それが柔軟さを欠いて固定化したり、未熟な防衛に偏ったりすると、症状や不適応につながる。","k":["自我","不安","アンナ・フロイト","抑圧","昇華","適応"],"p":"具体例を2〜3個添えると説得力が出る（例：反動形成＝憎い相手に過度に丁寧にふるまう）。防衛を「取り除くべきもの」と書かないこと。"},{"id":"repression","t":"抑圧","en":"repression","f":"seishin","a":"受け入れがたい欲動や記憶、観念を意識から締め出し、無意識にとどめておく防衛機制で、フロイトはこれを防衛の基本とみなした。抑圧されたものは消えるわけではなく、意識に戻ろうとする力をもち続け、夢や失錯行為、神経症の症状として偽装された形で回帰する（抑圧されたものの回帰）。意識的に考えないようにする抑制とは区別される。精神分析では、自由連想や解釈を通じて抑圧されたものを意識化し、それをめぐる葛藤を扱うことが治療の中心となった。","k":["防衛機制","無意識","回帰","抑制","意識化"],"p":"「抑圧」と「抑制」、「抑圧」と「否認」（外界の知覚を認めない）の区別が問われやすい。"},{"id":"transference","t":"転移","en":"transference","f":"seishin","a":"クライエントが、過去の重要な人物（多くは親）との関係で抱いた感情や態度、関係のパターンを、無意識のうちに治療者に向けて再現する現象。好意や信頼などの陽性転移と、敵意や不信などの陰性転移がある。フロイトは当初これを治療の障害とみたが、のちに、過去の葛藤が「今ここ」で生きた形で現れるものとして、治療の中心的な手がかりと位置づけた。転移を理解し解釈することで、クライエントは自らの関係のあり方を体験的に理解していく。","k":["過去","重要な人物/親","治療者","陽性転移","陰性転移","解釈"],"p":"「障害→手がかり」という位置づけの変化と、転移は日常の人間関係にも生じる普遍的な現象である点を押さえる。逆転移とセットで論述に出やすい。"},{"id":"countertransference","t":"逆転移","en":"countertransference","f":"seishin","a":"治療者がクライエントに対して抱く感情や反応をいう。フロイトは、治療者自身の未解決の葛藤による治療の障害とみなし、教育分析による克服を求めた。その後、ハイマン（Heimann, P.）らによって、逆転移はクライエントの無意識を理解するための重要な手がかりであるとする見方が広まった。ラッカーは、クライエントの自己に同一化する融和型と、クライエントの内的対象に同一化する補足型を区別した。逆転移を行動化せず、吟味して理解に用いることが求められる。","k":["治療者","障害","ハイマン/Heimann","手がかり","行動化"],"p":"「感じてはいけない感情」ではなく「感じたうえで吟味する材料」と書く。スーパービジョンや教育分析の意義と結びつけると深まる。"},{"id":"resistance","t":"抵抗","en":"resistance","f":"seishin","a":"治療の過程で、無意識的な内容の意識化や変化に逆らって働く、クライエントの心の動きをいう。沈黙、遅刻やキャンセル、話題をそらすこと、治療者への過度の同調などとして現れる。フロイトは当初これを克服すべき障害とみたが、抵抗には、つらい感情から自分を守ってきたその人なりのあり方が表れている。そのため、無理に取り除くのではなく、何から身を守ろうとしているのかを理解し、解釈して扱うことが治療の重要な部分となった。","k":["意識化","変化","沈黙/遅刻","守","解釈"],"p":"抵抗を「クライエントのやる気のなさ」と書くのは誤り。治療関係の中で意味をもつ現象として扱う姿勢を示す。"},{"id":"free-assoc","t":"自由連想法","en":"free association","f":"seishin","a":"精神分析の基本的な方法で、クライエントに、頭に浮かんだことを、不快であったり、くだらない・関係ないと思えたりしても、取捨選択せずにすべて話すよう求める（基本規則）。フロイトは、催眠や前額法を経てこの方法にいたった。連想の流れや途切れ、言いよどみなどに現れる抵抗や転移を手がかりに、無意識の内容を理解していく。古典的には寝椅子を用い、治療者は視野の外に座り、平等に漂う注意をもって聴く。","k":["頭に浮かんだ","基本規則","催眠","抵抗","平等に漂う注意","寝椅子"],"p":"治療者側の「平等に漂う注意」と対になっていることを書くと一段上の答案になる。"},{"id":"dream-work","t":"夢の作業","en":"dream-work","f":"seishin","a":"フロイトが『夢解釈』（1900年）で示した、夢の背後にある無意識的な願望（潜在内容）が、検閲をかいくぐって、実際に見た夢（顕在内容）へと変形される過程。複数の要素を一つにまとめる圧縮、重要な感情や意味を些細な要素に移す置き換え、思考を視覚的な像に変える表象可能性への顧慮（視覚化）、夢をまとまりのある筋書きに整える二次加工などからなる。フロイトは夢を「無意識への王道」と呼び、夢は願望充足であると考えた。","k":["潜在","顕在","圧縮","置き換え","二次加工","願望充足"],"p":"ユングの夢の見方（補償・目的論、拡充法）との比較で問われることが多い。"},{"id":"oedipus","t":"エディプス・コンプレックス","en":"Oedipus complex","f":"seishin","a":"フロイトが心的発達の中心に位置づけた葛藤。男根期（およそ3〜5歳）に、子どもが異性の親に愛情を向け、同性の親を競争相手として敵意を抱く一方、同性の親から罰せられることを恐れる（男児では去勢不安）という三者関係の葛藤をいう。ギリシア悲劇『オイディプス王』にちなむ。子どもは同性の親に同一化することでこの葛藤を解消し、その過程で超自我が形成される。フロイトは、これを神経症の中核的な葛藤とした。","k":["男根期","異性の親","同性の親","去勢不安","三者関係","超自我"],"p":"日本の「阿闍世コンプレックス」（母子の二者関係、許しによる罪悪感）との対比は上智に限らず頻出。"},{"id":"repetition","t":"反復強迫","en":"repetition compulsion","f":"seishin","a":"過去の苦痛な体験や関係のパターンを、本人の意図に反して繰り返してしまう傾向をいう。フロイトは、患者が過去を想起する代わりに行為として反復することに注目した。さらに『快原理の彼岸』（1920年）で、外傷的な夢の反復や、幼児の糸巻き遊び（いないいない／ばあ）を手がかりに、快原理では説明できない反復の背後に死の欲動を想定した。治療では、転移の中に現れる反復を理解し、想起と徹底操作へとつなげることが求められる。","k":["反復","快原理の彼岸/快感原則の彼岸","1920","死の欲動","転移","徹底操作"],"p":"トラウマの再演（再被害化）や、同じような相手を選び続ける恋愛関係など、臨床例と結びつけて説明できるように。"},{"id":"object-relations","t":"対象関係論","en":"object relations theory","f":"seishin","a":"人の心の発達と病理を、欲動そのものよりも、自己と他者（対象）との関係、とりわけ内面に取り入れられた内的対象との関係から理解しようとする精神分析の理論の総称。クラインを起点に、フェアベーン、ウィニコット、バリントらのイギリス独立学派、ビオンなどによって発展した。乳児期の母子関係で形成される内的対象関係が、その後の対人関係や転移の中で繰り返されると考え、治療では治療者との関係に表れる内的対象関係を理解し扱う。","k":["対象","内的対象","クライン/Klein","ウィニコット/Winnicott","母子関係","転移"],"p":"フロイトの欲動論（快を求める）とフェアベーンの「リビドーは対象を求める」の対比を一文入れると理論の転換点が示せる。"},{"id":"klein-pos","t":"妄想分裂ポジションと抑うつポジション","en":"paranoid-schizoid / depressive position","f":"seishin","a":"クライン（Klein, M.）が示した、乳児期の心のあり方の2つの様式。生後3〜4か月ごろまでの妄想分裂ポジションでは、乳児は対象を「良い乳房」と「悪い乳房」という部分対象に分裂させ、悪い部分を外に投影して迫害される不安（迫害不安）を抱く。続く抑うつポジションでは、良い面と悪い面が同じ一人の母親（全体対象）に属すると気づき、自分の攻撃性が愛する対象を傷つけたという抑うつ不安と罪悪感が生じ、償いの気持ちが芽生える。","k":["クライン/Klein","分裂","部分対象","迫害不安","全体対象","償い"],"p":"「段階」ではなく「ポジション（生涯を通じて行き来する心の構え）」と呼んだ理由を説明できると評価が高い。"},{"id":"proj-id","t":"投影同一化（投影性同一視）","en":"projective identification","f":"seishin","a":"クラインが1946年に記述した原始的な防衛機制で、自己の受け入れがたい部分を分裂させて対象の中に投げ入れ、対象をその部分と同一のものとして体験し、支配しようとする空想をいう。ビオンはこれを、乳児が耐えられない感情を母親に伝える正常なコミュニケーションの手段としても位置づけた。臨床では、クライエントが投げ入れた感情を治療者が実際に感じさせられることがあり、逆転移を通してクライエントを理解する手がかりとなる。","k":["クライン/Klein","分裂","投げ入れ","ビオン/Bion","コミュニケーション","逆転移"],"p":"単なる「投影」との違い（相手が実際にその感情を感じるよう影響を与える、相互作用的な現象）を書くことが要点。"},{"id":"transitional","t":"移行対象","en":"transitional object","f":"seishin","a":"ウィニコット（Winnicott, D. W.）が示した概念で、乳幼児が肌身離さず持ち歩く毛布やぬいぐるみなど、母親から心理的に分離していく過程で、母親の代わりとして慰めを与える対象をいう。それは乳児にとって、自分が作り出したものでも外から与えられたものでもあるような、内的世界と外的現実の中間にある「移行領域（可能性空間）」に属している。ウィニコットは、この中間領域が、のちの遊びや芸術、文化的な体験の源になると考えた。","k":["ウィニコット/Winnicott","毛布/ぬいぐるみ","分離","中間/移行領域","遊び"],"p":"「どちらのものか問わない」という逆説を保つことが大切だ、というウィニコットの指摘は遊戯療法や芸術療法の論述にも使える。"},{"id":"good-enough","t":"ほどよい母親と抱える環境","en":"good-enough mother / holding","f":"seishin","a":"ウィニコットの概念。ほどよい母親とは、完璧な母親ではなく、乳児の欲求にほぼ適切に応えつつ、成長に応じて少しずつ失敗することで、乳児が現実に適応していくのを助ける母親をいう。抱える環境（ホールディング）とは、乳児が身体的にも心理的にも安心して存在し続けられるよう、母親が支え守る環境のことである。心理療法も、治療者が一貫した枠組みと態度でクライエントを抱える環境を提供することで、本当の自己が育つ場となると考えられる。","k":["ウィニコット/Winnicott","完璧","失敗","ホールディング/抱える","本当の自己"],"p":"「失敗」の積極的な意味（脱錯覚）を書けるかがポイント。治療者の「完璧でなさ」が治療的に働く局面の議論にもつながる。"},{"id":"container","t":"コンテイナー／コンテインド","en":"container / contained","f":"seishin","a":"ビオン（Bion, W. R.）の概念。乳児は耐えがたい感情や感覚（ベータ要素）を投影同一化によって母親に投げ入れ、母親はそれを受け止め、もの想い（レヴァリー）を通して意味のあるもの（アルファ要素）に変形して返す。この変形の働きをアルファ機能と呼び、受け止める側をコンテイナー、受け止められるものをコンテインドと呼ぶ。この経験の積み重ねにより、乳児は自ら考え、感情を抱えておく力を内在化する。治療者の機能を説明する枠組みとしても用いられる。","k":["ビオン/Bion","ベータ要素","投影同一化","もの想い/レヴァリー","アルファ機能","考え"],"p":"ウィニコットの「抱える環境」との異同（身体的・環境的な支え／感情を消化し意味に変える心の働き）を比較できるようにしておく。"},{"id":"kohut","t":"自己心理学","en":"self psychology","f":"seishin","a":"コフート（Kohut, H.）が、自己愛の病理の治療経験から創始した精神分析の理論。健康な自己愛の発達には、子どもの自己を映し返して認める存在、理想化できる存在、自分と似ていると感じられる存在といった自己対象の応答が必要だと考え、それが得られないと、自己がまとまりを欠いて傷つきやすくなるとした。治療では、鏡転移・理想化転移・双子（分身）転移として現れる自己対象転移を受け止め、共感を観察と理解の方法として重視する。","k":["コフート/Kohut","自己愛","自己対象","鏡転移","理想化","共感"],"p":"ロジャーズの共感との比較（コフートは共感を「代理の内省」という観察の方法とした）は思想系の論述でも使える。"},{"id":"ego-psych","t":"自我心理学","en":"ego psychology","f":"seishin","a":"フロイトの構造論をもとに、自我の働きに焦点を当てて発展した精神分析の流れ。アンナ・フロイトの防衛機制の研究に続き、ハルトマン（Hartmann, H.）は、知覚、記憶、運動などのように葛藤とは独立に発達する「葛藤外の自我領域」と、環境への適応の働きを論じた。エリクソンの心理社会的発達理論も、この流れの中から生まれた。主にアメリカで主流となり、自我の強さや防衛の評価、支持的な心理療法の理論的な基盤となった。","k":["自我","アンナ・フロイト","ハルトマン/Hartmann","葛藤外","適応","エリクソン"],"p":"対象関係論（イギリス）との地域・関心の違いを押さえると、精神分析の「学派の地図」が描ける。"},{"id":"lacan","t":"鏡像段階","en":"mirror stage","f":"seishin","a":"ラカン（Lacan, J.）が提唱した概念で、生後6〜18か月ごろの乳児が、鏡に映った自分の像を見て、歓喜とともにそれを自分だと認める段階をいう。運動機能が未熟で、ばらばらな身体を生きている乳児は、鏡の中のまとまった像に自分を同一化することで、はじめて統一された自己のイメージ（自我）を得る。しかし、その自我は外にある像、すなわち他者を通して作られた想像的なものであるため、自我は根本的に疎外を含み、他者との鏡像的な競合関係を生むとされる。","k":["ラカン/Lacan","生後6","鏡","統一","想像的","疎外"],"p":"「自我は自分の中心ではなく、他者の像からできている」という逆説がポイント。自我心理学への批判という文脈も添えられるとよい。"},{"id":"mentalization","t":"メンタライゼーション","en":"mentalization","f":"seishin","a":"フォナギー（Fonagy, P.）らが提唱した概念で、自分や他者の行動を、その背後にある欲求、感情、信念、意図などの心の状態と結びつけて理解する心の働きをいう。安定した愛着関係の中で、養育者が子どもの心の状態を読み取って映し返すことを通じて発達すると考えられる。愛着理論と精神分析を統合する視点から、境界性パーソナリティ障害の人では強い感情の中でこの働きが損なわれやすいとされ、それを高めるメンタライゼーションに基づく治療（MBT）が開発された。","k":["フォナギー/Fonagy","心の状態","愛着","境界性パーソナリティ","MBT"],"p":"「心の理論」（発達心理学）との異同を問われることがある。メンタライゼーションは感情的な関係の中での働きを重視する。"},{"id":"interpretation","t":"解釈と徹底操作","en":"interpretation / working through","f":"seishin","a":"解釈とは、クライエントの語りや行動、転移などに表れている無意識の意味を、治療者が理解して言葉で伝えることであり、精神分析的心理療法の中心的な介入である。表層から深層へ、防衛から欲動へ、タイミングを見て伝えることが原則とされる。一度の解釈で洞察が得られても、変化はすぐには定着しない。同じ葛藤が形を変えて繰り返し現れるたびにそれを扱い、抵抗を乗り越えて洞察を深めていく過程が必要であり、これを徹底操作という。","k":["無意識","転移","タイミング","洞察","繰り返","抵抗"],"p":"来談者中心療法の「反射（伝え返し）」との違い（意識されていない意味を言葉にする）を対比して書けるように。"},{"id":"treatment-structure","t":"治療構造","en":"therapeutic structure","f":"seishin","a":"小此木啓吾が体系化した概念で、治療者とクライエントの交流を規定する条件の総体をいう。面接の時間、頻度、場所、料金、対面か寝椅子かといった外面的な治療構造と、秘密を守るという約束や自由連想の規則、治療目標の取り決めなどの内面的な治療構造がある。治療構造は治療を安定させ、クライエントを守る枠組みである。同時に、遅刻、時間延長の要求、料金をめぐる問題など、枠に対する反応の中に転移や葛藤が表れるため、それ自体が理解の手がかりとなる。","k":["小此木啓吾","時間","料金","外面的","内面的","枠"],"p":"事例問題（終了間際に重要な話をする、延長を求めるなど）で「枠をどう守り、どう理解に使うか」を書く際の理論的根拠になる。"},{"id":"amae","t":"甘え","en":"amae","f":"seishin","a":"土居健郎が『「甘え」の構造』（1971年）で論じた、日本語に固有の言葉を手がかりとする精神分析的な概念。相手の好意をあてにし、それに依存して受け入れられたいと願う感情で、乳児が母親との一体感を求める気持ちに源をもつ。土居は、これがバリントの受身的対象愛に通じるものであり、日本人の心性や対人関係を理解する鍵であると同時に、人間に普遍的な心理であると考えた。すねる、ひがむ、ひねくれるなどは、甘えが満たされないときの心の動きとされる。","k":["土居健郎","「甘え」の構造/甘えの構造","依存","一体感","バリント/受身的対象愛","普遍"],"p":"「日本人特有」とだけ書くのは不十分。土居自身は普遍的な心理として論じた点を押さえる。治療関係の中の甘え（転移）として論じることもできる。"},{"id":"ajase","t":"阿闍世コンプレックス","en":"Ajase complex","f":"seishin","a":"古澤平作が仏典の阿闍世王の物語をもとに提唱し、小此木啓吾が発展させた日本の精神分析の概念。母への一体感の願望と、母が自分を生む前に抱いた身勝手な思いへの怨み（未生怨）をめぐる、母と子の間の愛と憎しみの葛藤をいう。父との競争と処罰への恐れを軸とするエディプス・コンプレックスに対し、母と子が互いの罪を許し合うことで生じる、「とろかされる」ような罪意識（懺悔心）を重視する点に特徴がある。","k":["古澤平作","小此木啓吾","未生怨","母","許","エディプス"],"p":"処罰型の罪悪感（エディプス）と、許されることで生じる罪悪感（阿闍世）の対比を一文で書けるようにしておく。"},{"id":"negative-capability","t":"ネガティブ・ケイパビリティ","en":"negative capability","f":"seishin","a":"詩人キーツ（Keats, J.）が書簡の中で、性急に事実や理由を求めず、不確かさや謎、疑いの中にとどまっていられる能力として述べた言葉。精神分析家のビオンは、これを治療者に必要な態度として取り上げ、記憶や欲望、早まった理解にとらわれずに、クライエントとの関わりに開かれていることの重要性を説いた。答えの出ない事態や、わからなさに耐える力として、安易な助言や結論で不安を解消しようとしない心理臨床の姿勢を考える手がかりとなる。","k":["キーツ/Keats","不確かさ","ビオン/Bion","記憶","わからなさ/答えの出ない"],"p":"「人を理解するとは」「心理臨床家に求められる資質」といった思想系の論述で使える。"},{"id":"neutrality","t":"中立性と禁欲原則","en":"neutrality / abstinence","f":"seishin","a":"精神分析的心理療法における治療者の基本的な態度。中立性とは、クライエントの心のどの部分（欲動、自我、超自我）にも、また人生上の選択にも肩入れせず、価値判断や助言を控えて等しい距離に立つことをいう。禁欲原則とは、クライエントの転移的な欲求を治療関係の中で実際には満たさず、言葉で理解することをめざす原則である。これらは冷淡さや無関心を意味するのではなく、クライエントが自分の心を自由に探索できる空間を守るための態度である。","k":["中立","肩入れ","禁欲","転移","満たさ","冷淡/無関心"],"p":"来談者中心療法の「無条件の肯定的配慮」と比較させる問題も考えられる。どちらも「判断を押しつけない」点では共通する。"},{"id":"collective-unc","t":"集合的無意識","en":"collective unconscious","f":"jung","a":"ユング（Jung, C. G.）が提唱した概念で、個人の体験にもとづく個人的無意識のさらに深層にある、人類に共通する普遍的な無意識の層をいう。個人的無意識が主にコンプレックスからなるのに対し、集合的無意識は元型からなる。世界各地の神話や昔話、宗教的な象徴、夢などに似たイメージが繰り返し現れることの根拠とされた。フロイトの無意識が抑圧された個人的な内容を中心とするのに対し、ユングは無意識を、創造的で目的をもつものとしてとらえた。","k":["ユング/Jung","個人的無意識","普遍/人類","元型","神話/昔話","フロイト"],"p":"フロイトとの比較（個人的・抑圧されたもの／普遍的・創造的なもの、因果論／目的論）は最頻出の論点。"},{"id":"archetype","t":"元型","en":"archetype","f":"jung","a":"ユングが集合的無意識の内容として想定した、人類に共通するイメージや行動を生み出す心の型。元型そのものは意識でとらえることができず、夢や神話、昔話、宗教などに現れる元型的イメージを通して知られる。代表的なものに、影、ペルソナ、アニマ・アニムス、グレートマザー、老賢者、トリックスター、自己（セルフ）などがある。元型的イメージは強い情動を伴い、人を魅了したり圧倒したりする力（ヌミノース性）をもつ。","k":["ユング/Jung","集合的無意識","元型的イメージ","夢","神話","影"],"p":"「元型」と「元型的イメージ」を区別して書けるかがポイント（型そのものは直接知りえない）。"},{"id":"shadow","t":"影","en":"shadow","f":"jung","a":"ユングの元型の一つで、その人が意識的な自我の態度と相いれないために、受け入れずに生きてこなかった心の側面をいう。多くは否定的な性質として体験されるが、生きられてこなかった肯定的な可能性を含むこともある。影は他者に投影されやすく、理由もなく強い嫌悪を感じる相手に、自分の影を見ていることがある。影を自分の一部として認め、意識と関係をもたせていくこと（影の統合）は、個性化の過程の重要な段階とされる。","k":["元型","受け入れ","生きてこなかった/生きられてこなかった","投影","統合","個性化"],"p":"個人的な影と、人類に共通する悪としての普遍的な影の区別まで書けると深い。「悪いもの」とだけ書かないこと。"},{"id":"persona","t":"ペルソナ","en":"persona","f":"jung","a":"古代劇で役者がつけた仮面に由来するユングの概念で、人が社会の中で役割を果たすために身につける外的な態度や顔をいう。教師らしさ、親らしさなど、ペルソナは社会に適応するうえで必要なものである。しかし、ペルソナと自分自身を同一視しすぎると、内面の感情や個性が見失われ、硬直した生き方となる。逆に、ペルソナが十分に育たないと社会への適応が難しくなる。ペルソナと内的な心との釣り合いをとることが課題となる。","k":["仮面","社会","役割","適応","同一視"],"p":"「偽りの自分＝悪」と書かず、必要な機能と過剰同一化の危険の両面を書く。"},{"id":"anima","t":"アニマとアニムス","en":"anima / animus","f":"jung","a":"ユングの元型で、男性の無意識にある女性像をアニマ、女性の無意識にある男性像をアニムスと呼ぶ。外界との関係をつかさどるペルソナに対して、内界との関係をつかさどる「魂」のイメージとされ、夢や芸術、恋愛における強い引きつけ（投影）として現れる。意識の態度を補う働きをもち、これと関わることが個性化の過程で重要とされる。ただし、性別による二分法を前提とした概念であるため、現代ではジェンダー観の変化を踏まえた再検討もなされている。","k":["男性","女性","無意識","魂","投影","個性化"],"p":"現代的な批判（性別二元論）に一言ふれると、知識を相対化して扱えることを示せる。"},{"id":"self-jung","t":"自己（セルフ）","en":"the Self","f":"jung","a":"ユングの心理学における、意識と無意識を含めた心全体の中心であり、心の全体性を表す元型。自我が意識の中心であるのに対し、自己は自我を超えた、より大きな心の中心とされる。円や四角を基本とする対称的な図形であるマンダラや、神のイメージ、賢者などの象徴として、夢や表現に現れる。自我が自己との関係を深め、心の全体性を実現していく過程が個性化の過程であり、自己は心の統合を導く目標でもある。","k":["意識と無意識","全体","自我","マンダラ","個性化"],"p":"「自我（ego）」との区別が最重要。日常語の「自己」と混同しないよう、セルフと併記するとよい。"},{"id":"individuation","t":"個性化の過程","en":"individuation process","f":"jung","a":"ユングが心理的な発達の目標とした、その人が本来の自分自身になっていく過程をいい、自己実現の過程とも呼ばれる。自我が、ペルソナとの過度な同一視から離れ、影やアニマ・アニムスなどの無意識の内容と向き合い、関係を結びながら、心全体の中心である自己に近づいていく。ユングは、とくに人生の後半（「人生の正午」以降）にこの課題が重要になると考えた。社会から孤立して個人主義的になることではなく、集合的なものとの関係の中で自分らしさを生きることである。","k":["本来","自己実現","影","自己","人生の後半/人生の正午","個人主義"],"p":"中年期の危機と結びつけて論じられることが多い。エリクソンの生殖性や統合と比較するのも一案。"},{"id":"complex","t":"コンプレックス","en":"complex","f":"jung","a":"ユングが言語連想検査の研究から見いだした概念で、ある感情によって結びつけられた心的内容の集まり（感情によって色づけられた複合体）をいう。特定の刺激語に対して、反応時間の遅れ、反応の欠如、同じ語の反復などの乱れが生じ、その背後に特定のコンプレックスが想定された。コンプレックスは意識から相対的に自律して働き、本人の意図に反して言動を支配することがある。日本語の日常語でいう「劣等感」は、劣等コンプレックスの一例にすぎない。","k":["ユング/Jung","言語連想","感情","反応時間","自律","劣等感"],"p":"実験的な研究（言語連想検査）から生まれた概念である点は、ユングが実証的な研究者でもあったことを示す材料になる。"},{"id":"trickster","t":"トリックスター","en":"trickster","f":"jung","a":"世界各地の神話や昔話に登場する、いたずら者やぺてん師の姿をとる元型的な存在。北米先住民の神話のコヨーテやワタリガラス、北欧神話のロキ、ギリシア神話のヘルメスなどが知られる。既存の秩序や境界を気ままに破り、混乱や破壊をもたらすが、その結果として新たな秩序や変化が生まれるという、破壊と創造の両義性をもつ。臨床では、停滞した状況を思いがけず動かす存在として、また子どもの問題行動が家族に変化をもたらす働きを理解する視点として論じられる。","k":["神話/昔話","いたずら","秩序","境界","破壊と創造/両義","変化"],"p":"「ずる賢い者」とだけ書かず、両義性と「変化をもたらす」機能を中心に書く。治療者自身がトリックスター的に働く場面の議論もある。"},{"id":"great-mother","t":"グレートマザー（太母）","en":"Great Mother","f":"jung","a":"ユングの元型の一つで、母なるものの普遍的なイメージ。生み、育て、包み込む肯定的な側面と、抱え込み、呑み込み、自立を妨げる否定的な側面の両面をもつ。大地や海、洞窟、女神、魔女や山姥などの像として、神話や昔話に現れる。河合隼雄は、すべてを平等に包み込む母性原理が強い日本の社会と心性の特徴を論じ、その長所とともに、個の確立の難しさや、不登校などの問題の背景にもふれた。","k":["元型","母","育て","呑み込","河合隼雄","母性原理"],"p":"実際の母親とイメージとしての母（元型）を区別して書く。母性原理と父性原理（切る・分ける）の対比も押さえておく。"},{"id":"wise-old-man","t":"老賢者","en":"wise old man","f":"jung","a":"ユングの元型の一つで、知恵や洞察、精神的な導きを象徴する老人のイメージ。夢や神話、昔話の中で、主人公が困難に陥ったときに現れ、助言や道具を与えて道を示す存在として描かれる（魔法使い、仙人、隠者など）。意識だけでは解決できない状況で、無意識から現れる意味や方向性を表すとされる。一方で、その力に同一化すると、自分が特別な知恵をもつかのように思い込む誇大な状態（インフレーション）に陥る危険もある。","k":["元型","知恵","導き/助言","夢","同一化","インフレーション"],"p":"治療者が「老賢者」と同一化して万能的になる危険（クライエントからの理想化を引き受けすぎる）と結びつけると臨床的。"},{"id":"compensation","t":"補償","en":"compensation","f":"jung","a":"ユングの心理学における無意識の基本的な働きで、意識の態度が一面的になったときに、無意識がそれと反対の傾向を示し、心全体のバランスを回復させようとすることをいう。たとえば、ふだん謙虚すぎる人が夢の中で尊大にふるまう場合、その夢は意識の一面性を補っていると考えられる。ユングは夢を、フロイトのように偽装された願望充足とみるのではなく、意識の状況に対する無意識からのメッセージ（補償）としてとらえた。","k":["無意識","一面","バランス","夢","願望充足","フロイト"],"p":"アドラーの「補償」（劣等感の補償）と同じ語だが意味が異なる点に注意。"},{"id":"synchronicity","t":"共時性","en":"synchronicity","f":"jung","a":"ユングが提唱した概念で、因果的な関係がないにもかかわらず、心の内的な状態と外界の出来事が、意味のある形で一致して起こる現象をいう（意味のある偶然の一致）。ユングは物理学者パウリとの共著（1952年）で論じた。因果律だけでは説明できない、心と物質の間の非因果的な連関を想定するものである。心理療法の中でも、クライエントの内的な変化と外的な出来事が呼応して起こるように感じられることがあり、その意味を考えることが重視される。","k":["因果","意味のある偶然の一致/偶然","パウリ","内的","外界/外的"],"p":"科学的な実証の難しさにもふれつつ、「意味」を扱う心理臨床の態度として論じるとバランスがよい。"},{"id":"active-imagination","t":"能動的想像","en":"active imagination","f":"jung","a":"ユングが自らの無意識との対決の経験から発展させた方法で、意識をはっきり保ったまま、無意識から浮かんでくるイメージや人物に注意を向け、それと対話したり関わったりする技法である。イメージを意識的に操作して作り変えるのではなく、自律的に展開するのに任せつつ、自我が主体的に応答する点に特徴がある。絵や文章などの表現を伴うこともある。無意識の内容を意識に統合していく方法として、個性化の過程に役立つとされる。","k":["ユング/Jung","意識","イメージ","対話","自律","統合"],"p":"受け身の空想（白昼夢）との違い＝自我が主体的に関わる点を明確にする。"},{"id":"types","t":"心理学的タイプ（タイプ論）","en":"psychological types","f":"jung","a":"ユングが1921年の『タイプ論』で示した性格の類型論。関心やエネルギーが外界に向かう外向と、内界に向かう内向という2つの一般的態度と、思考・感情（合理機能）、感覚・直観（非合理機能）という4つの心理機能を組み合わせて、8つのタイプを考えた。最もよく発達した主機能に対し、その対極にある機能は未分化な劣等機能となり、無意識的に働くとされる。ユングにとってタイプ論は、人を分類するためよりも、自分の一面性に気づくための手がかりであった。","k":["1921","外向","内向","思考","直観","劣等機能"],"p":"特性論（ビッグファイブ）との違い（類型か連続量か）にふれると基礎心理学との橋渡しができる。"},{"id":"amplification","t":"拡充法","en":"amplification","f":"jung","a":"ユング派の夢やイメージの理解の方法で、夢に現れたイメージを、神話、昔話、宗教、文化的な象徴などの類似する素材と照らし合わせ、その意味を豊かに広げていく方法をいう。フロイトの自由連想が、イメージから連想をたどって背後の個人的な内容へと還元していく傾向をもつのに対し、拡充法はイメージそのものにとどまり、その元型的・普遍的な意味の広がりを明らかにしようとする。実際には、本人の個人的な連想と組み合わせて用いられる。","k":["ユング","神話","象徴","類似","自由連想","元型"],"p":"「還元的（フロイト）／拡充的（ユング）」という対比で書くと比較問題にそのまま使える。"},{"id":"constellation","t":"布置","en":"constellation","f":"jung","a":"ユング心理学で用いられる概念で、星々が星座を形づくるように、ばらばらに見える出来事や人物、イメージが、ある時に一つの意味あるまとまりとして配置されることをいう。元型やコンプレックスが活性化すると、内的な体験と外的な出来事が、それに沿った形で布置されるように感じられる。河合隼雄は、問題を原因と結果の連鎖で説明するのではなく、その人をめぐる全体の布置を読むことが、心理療法において重要であると強調した。","k":["星座","まとまり","元型/コンプレックス","河合隼雄","原因と結果/因果"],"p":"因果論的な理解（原因探し）と布置的な理解（全体の意味）の対比は、思想系の論述にも使える。"},{"id":"hollow-center","t":"中空構造","en":"hollow center structure","f":"jung","a":"河合隼雄が『古事記』の神話の分析から提唱した、日本人の心や社会の構造のモデル。『古事記』では、重要な三神の組のうち中心に位置する神（アメノミナカヌシ、ツクヨミ、ホスセリ）がほとんど何の働きもしないことに注目し、中心が空であることによって、対立する力が均衡を保つ構造であるとした。中心に絶対的な原理を置く西洋的な構造と対比される。対立を共存させる柔軟さがある一方で、責任の所在があいまいになりやすいという問題も指摘された。","k":["河合隼雄","古事記","中心","均衡","西洋/対比","責任"],"p":"日本文化論として「よい／悪い」で終わらせず、長所と短所の両面を示すのが河合の論じ方に沿う。"},{"id":"wounded-healer","t":"傷ついた治療者","en":"wounded healer","f":"jung","a":"ユングが、ギリシア神話で自ら癒えない傷を負いながら医術を教えたケンタウロスのケイローンになぞらえて述べた治療者像。治療者は、自らの傷つきや弱さを自覚しているからこそ、クライエントの苦しみに共感し、癒やしの過程に関わることができるという考え方である。グッゲンビュール＝クレイグは、治療者が自分の傷を忘れて「癒やす者」の側に一方的に立つと、治療関係の元型が分裂し、力の濫用が生じると警告した。教育分析の意義とも関わる。","k":["ケイローン","傷","共感","グッゲンビュール","力","教育分析"],"p":"「傷があるから治療者に向いている」という意味ではない。自覚と吟味（教育分析・スーパービジョン）が前提であることを明確にする。"},{"id":"ptsd","t":"心的外傷後ストレス障害（PTSD）","en":"posttraumatic stress disorder","f":"trauma","a":"実際にまたは危うく死ぬ、重傷を負う、性的暴力を受けるといった出来事を、直接体験したり目撃したりした後に生じる障害。DSM-5では、①侵入症状（フラッシュバック、悪夢など）、②持続的な回避、③認知と気分の陰性の変化（自責、否定的な信念、孤立感など）、④覚醒度と反応性の著しい変化（過覚醒、過剰な驚愕反応、睡眠の障害など）が1か月以上続き、生活に支障をきたすものとされる。持続エクスポージャー療法などのトラウマ焦点化治療の効果が示されている。","k":["死","侵入","回避","陰性","過覚醒/覚醒","1か月"],"p":"4つの症状群を正確に書けることが最低ライン。「出来事の後に誰もが発症するわけではない」点（多くは自然に回復する）も添えると適切。"},{"id":"asd-acute","t":"急性ストレス障害","en":"acute stress disorder","f":"trauma","a":"外傷的な出来事の後、3日から1か月の間に、侵入症状、陰性気分、解離症状、回避症状、覚醒症状が生じ、苦痛や生活上の支障をきたすものをいう（DSM-5）。症状が1か月を超えて続く場合は、PTSDの診断が検討される。出来事の直後に強いストレス反応が生じることは多くの人にみられる自然な反応でもあり、多くは時間とともに回復する。そのため急性期には、症状を病理化しすぎず、安全と安心の確保、生活の支援、心理的応急処置などが重視される。","k":["3日","1か月","解離","PTSD","自然な反応","心理的応急処置"],"p":"期間（3日〜1か月）とPTSDとの関係を正確に。急性期の介入として何を「しない」か（体験を詳しく語らせない）にもふれるとよい。"},{"id":"cptsd","t":"複雑性PTSD","en":"complex PTSD","f":"trauma","a":"虐待や家庭内暴力、監禁など、逃れることが難しい状況で、長期にわたって繰り返されたトラウマの後に生じやすい障害。ハーマン（Herman, J. L.）が1992年に提唱し、ICD-11で正式な診断名となった。PTSDの中核症状（再体験、回避、脅威の感覚）に加えて、感情制御の困難、否定的な自己概念（恥や無価値感）、対人関係の困難からなる「自己組織化の障害」を伴う。治療では、安全の確立、トラウマ記憶の処理、日常生活や人との結びつきの回復という段階的な支援が重視される。","k":["長期","ハーマン/Herman","ICD-11","感情制御","否定的な自己概念","対人関係"],"p":"DSM-5には独立した診断名としてはない点（ICD-11にある）を区別できると正確。境界性パーソナリティ障害との鑑別も論点になる。"},{"id":"dissociation","t":"解離","en":"dissociation","f":"trauma","a":"意識、記憶、同一性、感情、知覚、身体の感覚、行動など、通常は統合されている心の働きが、まとまりを失ったり断絶したりする状態をいう。ジャネ（Janet, P.）が早くから論じた。圧倒的な体験から心を守る働きとしても理解され、トラウマとの関連が深い。解離症群には、解離性同一症、解離性健忘、離人感・現実感消失症などがある。臨床では、話の途中でぼんやりする、記憶が抜けるなどのサインに気づき、安全とグラウンディングを重視して関わることが大切である。","k":["統合","ジャネ/Janet","トラウマ","解離性同一症","離人","グラウンディング"],"p":"フロイトの「抑圧」（水平の分割）とジャネの「解離」（垂直の分割）の対比は理論問題で使える。"},{"id":"tic","t":"トラウマインフォームド・ケア","en":"trauma-informed care","f":"trauma","a":"トラウマの影響についての知識を、支援に関わるすべての人や組織が共有し、あらゆる関わりに活かす支援の枠組み。米国のSAMHSAは、トラウマの広範な影響を理解し（Realize）、そのサインに気づき（Recognize）、知識を方針や実践に反映させて対応し（Respond）、再トラウマ化を防ぐ（Resist re-traumatization）ことを挙げている。「この人の何がおかしいのか」ではなく「この人に何があったのか」と問う視点に立ち、安全、信頼、選択、協働、エンパワメントを重視する。","k":["組織","SAMHSA","気づ","再トラウマ化","何があった","安全"],"p":"トラウマ治療（専門的な治療）とは別の「土台となる関わり方」である点を区別して書く。学校・施設・医療など場全体の取り組みとして論じられる。"},{"id":"pfa","t":"心理的応急処置（PFA）","en":"psychological first aid","f":"trauma","a":"災害や事件などの危機的な出来事に遭遇した直後の人々に対して行う、人道的で支持的な初期の支援。WHO版では、準備をしたうえで「見る（Look）」「聞く（Listen）」「つなぐ（Link）」を活動の原則とし、安全の確保、基本的なニーズへの対応、話を無理に聞き出さずに寄り添うこと、必要な支援や情報につなぐことなどを重視する。専門家だけが行うものではなく、トラウマ体験を詳しく語らせるといった侵襲的な介入を行わないことが特徴である。","k":["災害","WHO","見る","聞く","つなぐ","無理に"],"p":"心理的デブリーフィングとの対比（語らせない・強制しない）で書くと、エビデンスの変遷まで示せる。"},{"id":"pe","t":"持続エクスポージャー療法（PE）","en":"prolonged exposure therapy","f":"trauma","a":"フォア（Foa, E. B.）らが開発した、PTSDに対する認知行動療法。恐怖の記憶の構造が修正されることで回復が起こるとする情動処理理論にもとづく。心理教育と呼吸法に続き、トラウマ記憶を繰り返し想起して語る想像エクスポージャーと、安全だが避けている状況や場所に段階的に向き合う現実エクスポージャーを行う。回避が症状を維持していると考え、記憶に向き合うことで不安が低下し、出来事についての意味づけが修正されていく。","k":["フォア/Foa","PTSD","情動処理理論","想像エクスポージャー","現実エクスポージャー","回避"],"p":"「トラウマを思い出させるのは危険」という誤解に対し、安全な治療構造のもとで段階的に行うことを示すとよい。"},{"id":"tfcbt","t":"トラウマフォーカスト認知行動療法（TF-CBT）","en":"trauma-focused CBT","f":"trauma","a":"コーエン（Cohen, J. A.）らが開発した、トラウマを受けた子どもと養育者のための認知行動療法で、主に3〜18歳を対象とする。心理教育とペアレンティング、リラクセーション、感情の表現と調整、認知の対処、トラウマ・ナラティブの作成と処理、現実場面での段階的な曝露、親子の合同セッション、安全の強化という構成要素からなり、頭文字をとってPRACTICEと呼ばれる。養育者が治療に参加し、子どもを支える力を高める点に特徴がある。","k":["子ども","養育者","トラウマ・ナラティブ/ナラティブ","PRACTICE","段階"],"p":"子どもの支援では「養育者の参加」が鍵であること、非加害の養育者が子どもを信じ支えることの意味を書けると臨床的。"},{"id":"emdr","t":"EMDR（眼球運動による脱感作と再処理法）","en":"EMDR","f":"trauma","a":"シャピロ（Shapiro, F.）が開発したトラウマの治療法。トラウマ記憶のイメージや否定的な認知、身体の感覚に注意を向けながら、治療者の指の動きを目で追うなどの左右交互の刺激（両側性刺激）を加えることで、記憶の処理を促す。8段階の手続きからなり、適応的情報処理モデルを理論的な背景とする。PTSDへの効果が示され、国際的な治療ガイドラインでも推奨されているが、眼球運動そのものが効果に必要かどうかについては議論がある。","k":["シャピロ/Shapiro","両側性刺激/左右交互","8段階","適応的情報処理","PTSD"],"p":"効果の実証と、作用機序の議論を分けて書くと、研究を批判的に読む力を示せる。"},{"id":"cpt","t":"認知処理療法（CPT）","en":"cognitive processing therapy","f":"trauma","a":"レジック（Resick, P. A.）らが開発した、PTSDに対する認知療法。トラウマの後に生じた、出来事や自分、他者、世界についての偏った考え（スタックポイント）が回復を妨げると考える。「自分が悪かった」と出来事を元の信念に合わせて歪める同化や、「誰も信用できない」と信念を極端に変えすぎる過剰調節に気づき、ソクラテス式の問いかけや練習用紙を使って検討する。安全、信頼、力とコントロール、自尊心、親密さのテーマを扱う。","k":["レジック/Resick","スタックポイント","同化","過剰調節","ソクラテス"],"p":"「自責感」を扱う治療として、性暴力被害などの事例問題で根拠に使える。ピアジェの同化・調節との用語の対応にも気づけるとよい。"},{"id":"secondary-victim","t":"二次被害","en":"secondary victimization","f":"trauma","a":"犯罪や性暴力、災害などの被害を受けた人が、その後に、周囲の人や社会、支援や司法の過程などから受ける、さらなる精神的な傷つきをいう。「なぜ逃げなかったのか」と責めるような言葉、好奇の目、心ない報道、繰り返し事情を聴かれる負担などがその例である。被害者はもともと自責感を抱きやすく、二次被害によって回復が妨げられ、援助を求めなくなることもある。支援者自身が二次被害を与えうることを自覚し、被害者の尊厳と自己決定を尊重する関わりが求められる。","k":["被害","周囲","責め","報道","自責","支援者"],"p":"「なぜ」で始まる質問が責めとして響きやすいことなど、具体的な言葉づかいまで書けると実践的。"},{"id":"vicarious","t":"代理受傷と共感疲労","en":"vicarious traumatization / compassion fatigue","f":"trauma","a":"トラウマを負った人の話を繰り返し聴く支援者に生じる心理的な影響をいう。マッキャン（McCann, I. L.）とパールマン（Pearlman, L. A.）は、支援者自身の世界観や安全感、他者への信頼などの認知の枠組みが変化していくことを代理受傷と呼んだ。フィグリー（Figley, C. R.）は、共感的に関わることの代償として生じる、PTSDに類似した症状や疲弊を共感疲労（二次的外傷性ストレス）と呼んだ。スーパービジョン、セルフケア、組織的な支えが予防に重要である。","k":["支援者","代理受傷","パールマン/マッキャン","フィグリー/Figley","共感疲労","スーパービジョン"],"p":"個人の弱さではなく、職業上避けがたいリスクとして組織で対策する、という視点を示す。バーンアウトとの違いも整理しておく。"},{"id":"grief","t":"遷延性悲嘆症","en":"prolonged grief disorder","f":"trauma","a":"大切な人との死別の後、故人への強い思慕やとらわれが長く続き、深い感情的な苦痛と生活上の支障をきたす状態をいう。ICD-11では死別後少なくとも6か月、DSM-5-TRでは12か月以上（子どもは6か月以上）持続することが目安とされる。悲嘆そのものは自然な反応であり、文化や宗教によっても表れ方は異なるため、病的な悲嘆と通常の悲嘆を慎重に区別する必要がある。突然の死や暴力的な死別の後に生じやすく、悲嘆に焦点を当てた心理療法の効果が示されている。","k":["死別","思慕","6か月","12か月","自然な反応","文化"],"p":"「悲しみを病気にする」ことへの批判的な視点もあわせて書くと、診断の扱いに慎重であることを示せる。"},{"id":"ptg","t":"心的外傷後成長（PTG）","en":"posttraumatic growth","f":"trauma","a":"テデスキ（Tedeschi, R. G.）とカルフーン（Calhoun, L. G.）が提唱した概念で、外傷的な出来事やそれに伴う苦しみとのもがきの結果として生じる、ポジティブな心理的変容の体験をいう。他者との関係、新たな可能性、人間としての強さ、精神性的（スピリチュアルな）変容、人生への感謝の5つの領域がある。成長は苦痛がなくなることを意味せず、苦痛と共存しうる。支援者が成長を求めたり美化したりすると、当事者を追い詰める危険があることにも注意が必要である。","k":["テデスキ/Tedeschi","もがき","他者との関係","人生への感謝/感謝","苦痛","美化"],"p":"レジリエンス（回復・適応の維持）との違い（PTGは以前を超える変化）を書き分ける。"},{"id":"resilience","t":"レジリエンス","en":"resilience","f":"trauma","a":"逆境や強いストレスにさらされても、適応を保ち、あるいは回復していく力やその過程をいう。もとは物理学で「弾性」を意味する言葉である。かつては特別な個人の資質と考えられがちだったが、マステン（Masten, A. S.）は、ごく普通の適応のシステムの働きによって生じる「ありふれた魔法」であると述べた。個人の特性（自己効力感、感情調節など）だけでなく、家族や学校、地域とのつながりといった環境の要因との相互作用によって育まれる。","k":["逆境","回復","マステン/Masten","ありふれた魔法","環境","つながり"],"p":"「レジリエンスが低い人が悪い」という自己責任論にならないよう、環境要因を強調する。"},{"id":"crisis","t":"危機介入","en":"crisis intervention","f":"trauma","a":"危機とは、重要な問題に直面し、それまでの対処の方法では乗り越えられずに、心理的な均衡が崩れた状態をいう。リンデマン（Lindemann, E.）の火災による死別者の研究や、キャプラン（Caplan, G.）の危機理論を背景に発展した。危機状態は一般に数週間程度で何らかの均衡に向かうため、その時期に、短期間で集中的に、現在の問題に焦点を当てて援助し、危機以前の機能水準の回復をめざす。安全の確保、情緒的な支援、現実的な問題解決、社会資源の活用が中心となる。","k":["均衡","対処","リンデマン/Lindemann","キャプラン/Caplan","短期","社会資源"],"p":"危機は「危険」であると同時に「成長の機会」でもある、という両面性を書くと理論的な理解が示せる。"},{"id":"debriefing","t":"心理的デブリーフィング","en":"psychological debriefing","f":"trauma","a":"災害や事件の直後に体験者を集め、出来事の事実、考え、感情などを順を追って語ってもらう集団的な介入。消防士などの職業的な救援者を対象とした緊急事態ストレス・デブリーフィング（CISD）として広まった。しかし、その後の研究では、一回限りの単独の介入としてはPTSDの予防効果が認められず、むしろ症状を悪化させる可能性も指摘された。そのため現在では、急性期に体験を詳しく語らせることは推奨されず、心理的応急処置などが勧められている。","k":["直後","語","CISD","予防効果","悪化","心理的応急処置"],"p":"「善意の介入が害になりうる」ことをエビデンスで確かめる重要性の例として、研究法の論述にも使える。"},{"id":"aces","t":"逆境的小児期体験（ACEs）","en":"adverse childhood experiences","f":"trauma","a":"18歳までに経験した虐待、ネグレクト、家庭内暴力の目撃、家族の精神疾患や物質の乱用、両親の別離、家族の服役などの逆境的な体験をいう。フェリッティ（Felitti, V. J.）らによる1998年の大規模な研究で、こうした体験の数が多いほど、成人期のうつ病や自殺企図、依存症だけでなく、心疾患などの身体疾患のリスクも段階的に高まることが示された。予防や早期支援の重要性を示すとともに、トラウマインフォームド・ケアが広がる契機となった。","k":["18歳","虐待","フェリッティ/Felitti","数が多い","身体疾患","トラウマインフォームド"],"p":"ACE得点は集団のリスクを示すもので、個人の将来を決めるものではない（決定論にしない）という注意を添える。"},{"id":"window","t":"耐性の窓","en":"window of tolerance","f":"trauma","a":"シーゲル（Siegel, D. J.）が提唱した概念で、人が覚醒した状態を保ちながらも、感情や体験に圧倒されずに考えたり感じたりできる、ほどよい覚醒の範囲をいう。この範囲を上に超えると、不安やパニック、怒りなどの過覚醒の状態に、下に超えると、麻痺や解離、無気力などの低覚醒の状態に陥る。トラウマを受けた人では、この窓が狭くなりやすい。治療では、窓の中にとどまれるよう調整しながら体験を扱い、窓を広げていくことがめざされる。","k":["シーゲル/Siegel","覚醒","過覚醒","低覚醒","解離","広げ"],"p":"面接中のペース配分（話しすぎて圧倒されないように）の根拠として、事例問題で使える。"},{"id":"victim-law","t":"犯罪被害者等基本法","en":"Basic Act on Crime Victims","f":"trauma","a":"2004年に成立し、2005年に施行された法律で、犯罪被害者等が個人の尊厳にふさわしい処遇を保障される権利を有することを基本理念に掲げる。国や地方公共団体の責務を定め、相談と情報の提供、損害の回復と経済的な支援、保健医療・福祉サービスの提供、安全の確保、刑事手続への参加の機会の拡充、二次被害の防止などの施策を求めている。被害者の支援を国の責務として明確にし、民間の被害者支援団体や心理職を含む多様な機関の連携を促した。","k":["2004","尊厳","国","二次被害","刑事手続","連携"],"p":"心理職の役割を「個人の心理療法」に限らず、司法・行政・民間団体との連携の中に位置づけて書くとよい。"},{"id":"dsm-icd","t":"DSMとICD","en":"DSM / ICD","f":"iryo","a":"精神疾患の国際的な診断分類の体系。DSMはアメリカ精神医学会による『精神疾患の診断・統計マニュアル』で、2013年にDSM-5、2022年にその改訂版のDSM-5-TRが刊行された。ICDは世界保健機関（WHO）による疾病全般の国際分類で、2019年に採択されたICD-11が2022年に発効した。いずれも明確な基準にもとづく操作的診断によって診断の信頼性を高めたが、症状の数による診断は、背景にある個人の体験や文脈を見落としやすいという批判もある。","k":["アメリカ精神医学会","DSM-5","WHO/世界保健機関","ICD-11","操作的診断","信頼性"],"p":"「信頼性は高めたが妥当性は？」という問いを立てると、心理アセスメントとの関係を論じられる。"},{"id":"schizophrenia","t":"統合失調症","en":"schizophrenia","f":"iryo","a":"多くは思春期から青年期に発症する精神疾患で、生涯有病率はおよそ1％とされる。幻覚（とくに幻聴）や妄想、まとまりのない会話や行動などの陽性症状と、感情の平板化、意欲の低下、会話の貧困、社会的なひきこもりなどの陰性症状、さらに注意や記憶などの認知機能の障害がみられる。治療は抗精神病薬による薬物療法を基本に、心理教育、社会生活スキルトレーニング、家族支援、地域での生活支援などを組み合わせる。家族の感情表出（EE）が再発に影響する。","k":["1％/1%","幻覚/幻聴","妄想","陽性症状","陰性症状","抗精神病薬"],"p":"心理職の役割（心理教育、家族支援、リカバリーの支援）を具体的に書けるようにしておく。"},{"id":"depression","t":"うつ病","en":"major depressive disorder","f":"iryo","a":"抑うつ気分、または興味や喜びの喪失のいずれかを含み、食欲や体重の変化、睡眠の障害、精神運動の焦燥や制止、疲労感、無価値感や過剰な罪責感、思考力や集中力の低下、死についての反復的な思考などのうち5つ以上が、2週間以上ほぼ毎日続き、生活に支障をきたすものをいう（DSM-5）。治療には、休養、抗うつ薬、認知行動療法や対人関係療法などがある。自殺の危険の評価が欠かせず、回復期にも危険が高まることに注意が必要である。","k":["抑うつ気分","興味","2週間","5つ","自殺","認知行動療法"],"p":"事例問題では「休養の保障」「自殺リスクの確認」「医療との連携」の3点を外さないこと。"},{"id":"bipolar","t":"双極性障害","en":"bipolar disorder","f":"iryo","a":"気分が高揚し活動性が増して、睡眠欲求の減少、多弁、観念奔逸、誇大性、浪費などの無謀な行動がみられる躁病（または軽躁病）エピソードと、抑うつエピソードを繰り返す精神疾患。躁病エピソード（1週間以上）がみられる双極Ⅰ型と、軽躁病エピソード（4日以上）と抑うつエピソードがみられる双極Ⅱ型がある。うつ病と誤って診断されやすい。治療は気分安定薬などの薬物療法が中心で、心理教育によって再発のサインに気づき、生活リズムを整えることが重要である。","k":["躁病","軽躁","抑うつ","Ⅰ型/I型/1型","気分安定薬","生活リズム"],"p":"うつ病との鑑別（軽躁エピソードの既往の確認）が臨床上重要である点を書けるとよい。"},{"id":"bpd","t":"境界性パーソナリティ障害","en":"borderline personality disorder","f":"iryo","a":"対人関係、自己像、感情の不安定さと、著しい衝動性を特徴とするパーソナリティ障害。見捨てられることへの強い不安、理想化とこき下ろしの間を揺れ動く不安定な対人関係、同一性の混乱、自傷行為や自殺企図の繰り返し、慢性的な空虚感、激しい怒りなどがみられる。カーンバーグは、分裂などの原始的防衛と同一性拡散を特徴とする境界パーソナリティ構造を論じた。弁証法的行動療法やメンタライゼーションに基づく治療などの効果が示されている。","k":["見捨てられ","理想化","自傷","空虚","カーンバーグ/Kernberg","弁証法的行動療法"],"p":"治療者側の逆転移（振り回される、救いたくなる）と、一貫した治療構造・チームでの対応の重要性まで書けると臨床的。"},{"id":"autism","t":"自閉スペクトラム症","en":"autism spectrum disorder","f":"iryo","a":"DSM-5で、自閉症、アスペルガー障害などを連続体（スペクトラム）として統合した神経発達症。①社会的コミュニケーションおよび対人的相互反応における持続的な困難と、②行動、興味、活動の限定された反復的な様式（こだわり、常同行動、感覚の過敏さや鈍さを含む）を特徴とし、症状は発達の早期から存在する。支援では、本人の特性を理解し、見通しをもてるよう環境を構造化すること、二次障害を防ぐこと、家族や学校との連携が重要となる。","k":["スペクトラム/連続体","社会的コミュニケーション","反復","感覚","構造化","二次障害"],"p":"「障害」を本人の欠陥としてだけでなく、環境との相互作用で生じる困難として捉える視点（社会モデル、ニューロダイバーシティ）にもふれられるとよい。"},{"id":"adhd","t":"注意欠如・多動症（ADHD）","en":"attention-deficit/hyperactivity disorder","f":"iryo","a":"不注意（集中が続かない、忘れ物や紛失が多い、段取りが苦手など）と、多動性・衝動性（じっとしていられない、順番を待てない、思いつきで行動するなど）を特徴とする神経発達症。DSM-5では、いくつかの症状が12歳になる前から存在し、家庭と学校など2つ以上の場面でみられることが要件とされる。成人期まで続くことも多い。支援には、環境調整、ペアレント・トレーニング、本人の自己理解の支援、薬物療法などがあり、叱責の繰り返しによる自己評価の低下を防ぐことが大切である。","k":["不注意","多動性","衝動性","12歳","2つ以上","ペアレント・トレーニング"],"p":"二次障害（自己評価の低下、反抗、抑うつ）の予防の観点を必ず入れる。"},{"id":"anorexia","t":"神経性やせ症","en":"anorexia nervosa","f":"iryo","a":"必要量に比べて食事を制限し、年齢や身長に比べて有意に低い体重にいたる摂食障害。体重が増えることや肥満への強い恐怖、体重や体型についての認識の歪み（ボディイメージの障害）、低体重の深刻さを認めないことを特徴とし、摂食制限型と過食・排出型がある。思春期から青年期の女性に多く、精神疾患の中でも死亡率が高い。身体管理を含む医療との連携が不可欠で、家族を治療の資源とする家族療法（モーズレイ・モデル）や認知行動療法が用いられる。","k":["低い体重","肥満","ボディイメージ","死亡率","医療","家族療法"],"p":"心理療法だけで抱えず、身体の危険（低体重・電解質異常）に応じて医療と連携することが最優先である点を書く。"},{"id":"ocd","t":"強迫症","en":"obsessive-compulsive disorder","f":"iryo","a":"自分では不合理だとわかっていても繰り返し浮かんでくる考えやイメージ（強迫観念）と、それによる不安を打ち消すために、行わずにはいられない行為（強迫行為）を特徴とする。不潔恐怖と洗浄、確認行為、加害恐怖などが代表的である。強迫行為は一時的に不安を下げるが、それによって強迫観念が維持される。治療では、不安を引き起こす刺激にあえて向き合い、強迫行為をしないで不安が自然に下がるのを体験する曝露反応妨害法と、SSRIによる薬物療法の効果が示されている。","k":["強迫観念","強迫行為","不安","確認","曝露反応妨害法","SSRI"],"p":"家族が確認や保証に巻き込まれる（巻き込み）ことが症状を維持する点も、家族支援の論点として使える。"},{"id":"psychosomatic","t":"心身症とアレキシサイミア","en":"psychosomatic disease / alexithymia","f":"iryo","a":"日本心身医学会（1991年）は心身症を、身体疾患の中で、その発症や経過に心理社会的な因子が密接に関与し、器質的ないし機能的な障害が認められる病態と定義し、神経症やうつ病などに伴う身体症状は除くとした。胃・十二指腸潰瘍、気管支喘息、過敏性腸症候群などがある。シフネオス（Sifneos, P. E.）は心身症の患者に、自分の感情に気づいて言葉で表すことが難しいという特徴を見いだし、アレキシサイミア（失感情症）と名づけた。","k":["日本心身医学会","身体疾患","心理社会的","器質的","シフネオス/Sifneos","感情"],"p":"「心身症＝気のせい」ではなく身体疾患そのものである点を正確に。感情を言葉にしにくい人への面接の工夫（身体感覚から入る）も論点になる。"},{"id":"dementia","t":"認知症","en":"dementia","f":"iryo","a":"いったん正常に発達した認知機能が、脳の病気などによって持続的に低下し、日常生活や社会生活に支障をきたした状態をいう。原因疾患として、アルツハイマー型（記憶障害から始まることが多い）、血管性（まだらな症状、段階的な悪化）、レビー小体型（幻視、パーキンソン症状、認知の変動）、前頭側頭型（人格の変化、脱抑制、常同行動）などがある。記憶障害などの中核症状に加え、不安、抑うつ、徘徊、妄想などの行動・心理症状（BPSD）が生じ、本人と家族の負担となる。","k":["認知機能","アルツハイマー","血管性","レビー小体","前頭側頭","BPSD/行動・心理症状"],"p":"BPSDを「問題行動」と呼ばず、本人なりの意味や不安の表れとして理解する視点（パーソン・センタード・ケア）を添える。"},{"id":"mci","t":"軽度認知障害（MCI）","en":"mild cognitive impairment","f":"iryo","a":"本人や家族から認知機能の低下の訴えがあり、検査でも年齢に比べて記憶などの低下が認められるが、日常生活はおおむね自立しており、認知症とは診断されない状態をいう。認知症の前段階として注目され、一部は年を経て認知症に移行するが、正常な状態に戻る人や、変化しない人もいる。早期に気づくことで、運動や社会参加などの生活習慣の見直し、治療可能な原因の検索、本人の意思を尊重した将来の準備につなげることができる。","k":["認知機能","日常生活","自立","認知症","移行","戻る"],"p":"「必ず認知症になる」と書かないこと。告知や心理的な支援（不安への対応）も論点になる。"},{"id":"delirium","t":"せん妄","en":"delirium","f":"iryo","a":"身体疾患や薬物、手術、脱水などを原因として急に生じる、注意の障害を中心とした意識障害。見当識障害、幻覚、興奮、睡眠と覚醒のリズムの乱れなどを伴い、症状が一日の中で変動し、夕方から夜間に悪化しやすい。活動が低下する低活動型は見逃されやすい。高齢者の入院や手術後に多く、認知症との鑑別や合併に注意が必要である。原因となる身体の状態の治療が基本であり、環境調整や家族の付き添いなどの非薬物的な対応が重要である。","k":["身体疾患","急","注意","意識障害","変動","低活動型"],"p":"認知症との違い（急性発症・変動・意識障害）を表で整理しておくと、比較問題にも対応できる。"},{"id":"pcc","t":"パーソン・センタード・ケア","en":"person-centred care","f":"iryo","a":"キットウッド（Kitwood, T.）が提唱した認知症ケアの考え方で、認知症の人を、病気の症状の集まりとしてではなく一人の「人」として尊重し、その人の視点に立ってケアを行うことをいう。認知症の人の状態は、脳の障害だけでなく、性格、生活歴、健康状態、そして周囲との関わり（社会心理）の影響を受けると考える。周囲の不適切な関わりが本人の「その人らしさ（パーソンフッド）」を損なうことを指摘し、観察にもとづく評価法である認知症ケアマッピングも開発された。","k":["キットウッド/Kitwood","人","視点","生活歴","その人らしさ/パーソンフッド","認知症ケアマッピング"],"p":"ロジャーズのパーソン・センタードとの理念的なつながりにふれると、臨床心理学の知が他領域に広がった例として書ける。"},{"id":"reminiscence","t":"回想法","en":"reminiscence therapy","f":"iryo","a":"高齢者が過去の出来事や人生を振り返って語ることを、聴き手が受容的・共感的に聴くことで、心理的な安定や自己の肯定をはかる方法。精神科医のバトラー（Butler, R. N.）は1963年に、高齢者の回想を、人生を振り返り統合しようとする自然で意味のある過程（ライフレビュー）として積極的に評価した。一般的な回想法は、懐かしい写真や道具などを手がかりに個人やグループで行われ、認知症の人の意欲やコミュニケーションの促進、介護者との関係づくりにも用いられる。","k":["高齢者","過去","バトラー/Butler","1963","ライフレビュー","認知症"],"p":"エリクソンの「統合 対 絶望」と結びつけると発達理論との接続が示せる。つらい記憶が想起される可能性への配慮も添える。"},{"id":"preparation","t":"プレパレーション","en":"preparation","f":"iryo","a":"病気の子どもが、検査や処置、手術、入院などによって受ける心理的な混乱を最小限にし、その子なりに乗り越えていけるよう、発達段階に応じた方法で事前に説明し、心の準備を支える関わり。人形や絵本、実際の医療器具などを用いて、何が起こるのか、どんな感覚がするのか、どうすればよいのかを伝える。処置中に気をそらす工夫（ディストラクション）や、処置後に遊びを通して体験を表現できるよう支えることも含む。子どもの権利と主体性を尊重する考えにもとづく。","k":["子ども","処置","発達段階","人形/絵本","ディストラクション","権利"],"p":"「だまして連れて行く」ことが不信と恐怖を強めること、うそをつかない説明の大切さを書く。"},{"id":"palliative","t":"緩和ケアとトータルペイン","en":"palliative care / total pain","f":"iryo","a":"緩和ケアとは、生命を脅かす病に関連する問題に直面している患者と家族のQOLを、痛みやその他の身体的、心理社会的、スピリチュアルな問題の早期の評価と対応によって改善するアプローチである（WHO、2002年）。ホスピス運動を始めたソンダース（Saunders, C.）は、終末期の患者の苦痛を、身体的、精神的、社会的、スピリチュアルな苦痛が相互に関連する全人的な苦痛（トータルペイン）としてとらえた。心理職は患者と家族の心理的な支援や、医療者の支援を担う。","k":["QOL","WHO","家族","ソンダース/Saunders","トータルペイン/全人的","スピリチュアル"],"p":"緩和ケアは「終末期だけ」ではなく診断時から行われる点（早期からの緩和ケア）を正確に書く。"},{"id":"kubler-ross","t":"死の受容過程","en":"stages of dying","f":"iryo","a":"キューブラー＝ロス（Kübler-Ross, E.）が、約200人の死にゆく患者への面接をもとに『死ぬ瞬間』（1969年）で示した心理的な過程。①否認と孤立、②怒り、③取引、④抑うつ、⑤受容の5段階からなり、この過程を通じて希望が保たれるとされた。ただし、すべての人がこの順序をたどるわけではなく、段階が行きつ戻りつしたり、重なったりすることも多い。段階を当てはめて患者を評価するのではなく、その人なりの過程に寄り添うための視点として用いるべきである。","k":["キューブラー","否認","怒り","取引","受容","順序"],"p":"段階論の限界（順序の固定化、受容を目標として押しつけない）にふれると評価が上がる。"},{"id":"ee","t":"感情表出（EE）","en":"expressed emotion","f":"iryo","a":"家族が患者に対して表す感情の質と量をいい、ブラウン（Brown, G. W.）やレフ（Leff, J.）らの研究によって、統合失調症の再発との関連が明らかにされた。批判的なコメント、敵意、情緒的な巻き込まれすぎ（過度の心配や自己犠牲）が多い高EEの家族と暮らす患者は、低EEの家族と暮らす患者よりも再発率が高い。高EEは家族の病理ではなく、病気についての情報不足や介護の負担の大きさを反映したものと考えられ、家族心理教育によって家族を支えることが再発予防に有効とされる。","k":["家族","統合失調症","再発","批判","巻き込まれ","家族心理教育"],"p":"「家族が悪い」という家族病因論にしないことが最重要。家族も支援の対象であることを明確に。"},{"id":"liaison","t":"コンサルテーション・リエゾン","en":"consultation-liaison","f":"iryo","a":"総合病院などで、身体疾患の治療を受けている患者の精神的な問題について、精神科医や心理職が他科からの依頼に応じて助言や支援を行うこと（コンサルテーション）、さらに日常的に病棟のチームに加わって連携し、問題の予防や早期発見をはかること（リエゾン）をいう。せん妄、抑うつ、不安、治療への不適応などが対象となる。患者だけでなく、家族や医療スタッフを支援することも重要な役割であり、多職種によるチーム医療の一員として働く力が求められる。","k":["総合病院","他科","依頼","連携","せん妄","チーム医療"],"p":"心理職が病院で「面接室の外」で働く姿を具体的に描けると、医療領域の事例問題に強くなる。"},{"id":"pediatric","t":"小児医療における心理支援","en":"psychological care in pediatrics","f":"iryo","a":"病気の子どもとその家族を対象に、医療の場で行う心理的な支援。入院や治療に伴う不安や苦痛、学業や友人関係からの切り離され、発達の停滞、きょうだいへの影響など、子どもと家族は多くの困難に直面する。心理職は、子どもの発達段階に応じた病気の理解と表現を支え、遊びやプレパレーションを通じて、子どもが主体的に治療に向き合えるよう援助する。慢性疾患では長期的な成長に寄り添い、親の心理的な負担への支援や医療チームとの連携も欠かせない。","k":["子ども","家族","きょうだい","発達段階","遊び","連携"],"p":"「きょうだい」への支援は見落とされやすい論点。復学支援や移行期医療（小児科から成人診療科へ）にもふれられると広がりが出る。"},{"id":"assessment","t":"心理アセスメント","en":"psychological assessment","f":"assess","a":"クライエントの問題や状態を理解し、支援の方針を立てるために、面接、行動観察、心理検査などを用いて情報を集め、総合的に評価する過程をいう。問題点や症状だけでなく、本人の強みや資源、生活環境、問題が生じ維持されている仕組みを含めて理解することが重要である。アセスメントは支援の最初に一度だけ行うものではなく、関わりの中で仮説を立てては修正していく継続的な過程であり、その結果は本人や関係者と共有され、支援に活かされる必要がある。","k":["面接","行動観察","心理検査","強み/資源","仮説","共有"],"p":"「診断（ラベルを貼る）」との違い、「見立て」という日本の臨床の言葉との関係を論じられるようにしておく。"},{"id":"rorschach","t":"ロールシャッハ・テスト","en":"Rorschach test","f":"assess","a":"スイスの精神科医ロールシャッハ（Rorschach, H.）が1921年に『精神診断学』で発表した投映法の心理検査。左右対称のインクのしみからなる10枚の図版を見せて、それが何に見えるかを尋ね、その後、図版のどこに、どのような特徴から見えたのかを確認する。反応の領域、決定因（形、色彩、運動など）、形態水準、内容などを記号化して分析する。日本では片口法や包括システム（エクスナー）、近年はR-PASなどが用いられる。","k":["ロールシャッハ/Rorschach","1921","インク","10枚","決定因","包括システム/エクスナー"],"p":"「何を見たか（内容）」より「どう見たか（領域・決定因・形態水準）」を分析する検査である点が核心。"},{"id":"projective","t":"投映法","en":"projective techniques","f":"assess","a":"あいまいで多義的な刺激や、自由度の高い課題を与え、それに対する反応の中に、その人のパーソナリティや無意識的な側面が映し出される（投映される）と考える心理検査の総称。ロールシャッハ・テスト、TAT、P-Fスタディ、SCT、描画法などがある。回答の意図が読み取られにくく、意識的な操作を受けにくい点、言葉にならない内面をとらえうる点が長所とされる。一方、実施と解釈に熟練を要し、信頼性や妥当性の検証が難しいという限界がある。","k":["あいまい/多義的","パーソナリティ","無意識","ロールシャッハ","熟練","信頼性"],"p":"質問紙法との比較は頻出。被検者の負担や侵襲性（深い層を揺さぶること）への配慮も書けると臨床的。"},{"id":"tat","t":"主題統覚検査（TAT）","en":"Thematic Apperception Test","f":"assess","a":"マレー（Murray, H. A.）とモーガン（Morgan, C. D.）が1935年に発表した投映法。人物が登場する多義的な場面の絵を見せて、その場面に至るまでのいきさつ、今起きていること、登場人物の気持ち、この先どうなるかを含む物語を作ってもらう。マレーの欲求－圧力理論にもとづき、主人公の欲求と環境からの圧力などを分析し、対人関係のあり方や葛藤を理解する。子ども用に、動物を主人公とした図版のCATもある。","k":["マレー/Murray","1935","物語","欲求","圧力","CAT"],"p":"ロールシャッハ（知覚・認知の構造）とTAT（対人関係の内容・物語）の違いを押さえるとテスト・バッテリーの説明に使える。"},{"id":"lmt","t":"風景構成法","en":"Landscape Montage Technique","f":"assess","a":"中井久夫が1969年に考案した描画法。治療者がサインペンで画用紙に枠を描いて手渡し（枠づけ）、川、山、田、道、家、木、人、花、動物、石の10項目を順に一つずつ告げて描いてもらい、最後に足りないと思うものを付け加えて彩色し、一つの風景として完成させる。もとは統合失調症の患者に箱庭療法を適用できるかを探る目的で考案された。構成の仕方や項目の描き方から心の状態をとらえるとともに、治療的な交流の手段ともなる。","k":["中井久夫","1969","枠","川","10項目","統合失調症"],"p":"「枠づけ」が表現を守る（保護と制約）意味をもつ点、検査であり治療でもある二重性を書けると深い。"},{"id":"baum","t":"バウムテスト","en":"Baum test","f":"assess","a":"スイスのコッホ（Koch, K.）が1949年に体系化した描画法で、「実のなる木を1本描いてください」などと教示し、鉛筆でA4判の画用紙に木を描いてもらう。描かれた木の全体的な印象、用紙上の位置や大きさ、幹や枝、樹冠、根などの形態、筆圧や描線の特徴などから、その人のパーソナリティや心の状態、発達の水準などを理解する。実施が簡便で、子どもから高齢者まで幅広く用いられる。単一の特徴だけで判断せず、全体の印象から理解することが重要とされる。","k":["コッホ/Koch","1949","実のなる木","幹","全体","簡便"],"p":"「指標を機械的に当てはめない」という注意は、描画法全般の論述で使える。"},{"id":"pf","t":"P-Fスタディ","en":"Picture-Frustration Study","f":"assess","a":"ローゼンツヴァイク（Rosenzweig, S.）が考案した投映法で、日常的な欲求不満の場面が描かれた24の絵を見せ、話しかけられている人物の吹き出しにどう答えるかを記入してもらう。反応を、攻撃の方向（他責・自責・無責）と型（障害優位、自我防衛、要求固執）の組み合わせで分類し、欲求不満への反応の仕方を明らかにする。集団の一般的な反応との一致度を示すGCR（集団一致度）も求める。実施が容易で、児童用・青年用・成人用がある。","k":["ローゼンツヴァイク/Rosenzweig","欲求不満","24","他責","自責","GCR/集団一致度"],"p":"「攻撃（アグレッション）」を広い意味（自己主張を含む）で用いている点に注意。"},{"id":"sct","t":"文章完成法（SCT）","en":"Sentence Completion Test","f":"assess","a":"「子どもの頃、私は」「私の父は」のような書き出しの短い刺激文に続けて、思いつくことを自由に書いて文章を完成させてもらう投映法。家族、対人関係、自己像、将来の希望など、パーソナリティの幅広い側面を把握できる。刺激が言語的で意味が明確なため、他の投映法に比べると投映の水準は意識に近く、本人の意図による操作も受けやすい。一方で、実施が簡便で集団でも行え、記述そのものが面接の手がかりとなるため、テスト・バッテリーに組み込まれることが多い。","k":["刺激文","書き","自己像","意識","簡便","テスト・バッテリー"],"p":"投映法の中で「意識に近い水準」を測るという位置づけを、ロールシャッハとの対比で書けるように。"},{"id":"mmpi","t":"MMPI（ミネソタ多面人格目録）","en":"Minnesota Multiphasic Personality Inventory","f":"assess","a":"ハサウェイ（Hathaway, S. R.）とマッキンリー（McKinley, J. C.）が1943年に作成した、多数の項目からなる質問紙法の人格検査。精神医学的な診断群と健常群をよく判別する項目を経験的に選ぶ方法（経験的基準設定法）で作られた。心気症、抑うつ、ヒステリー、統合失調症などの10の臨床尺度に加え、受検態度の偏りを検討する妥当性尺度（疑問、虚構、頻度、修正）をもつ点に特徴がある。改訂版としてMMPI-2などがある。","k":["ハサウェイ","1943","質問紙","経験的","臨床尺度","妥当性尺度"],"p":"質問紙法の弱点（反応の歪み）を妥当性尺度で補おうとした工夫として説明すると、質問紙法一般の論述にも使える。"},{"id":"wechsler","t":"ウェクスラー式知能検査","en":"Wechsler intelligence scales","f":"assess","a":"ウェクスラー（Wechsler, D.）が開発した個別式の知能検査で、成人用のWAIS、児童用のWISC、幼児用のWPPSIがある。同年齢集団の中での相対的な位置を示す偏差IQを用いる点に特徴がある。WAIS-IVでは、全検査IQに加え、言語理解、知覚推理、ワーキングメモリー、処理速度の4つの指標得点が算出される。指標間や下位検査間のばらつき（個人内差）から認知の特性を理解でき、発達障害のある人などの支援計画に活かされる。","k":["ウェクスラー/Wechsler","WAIS","WISC","偏差IQ","指標","個人内差"],"p":"数値の高低だけでなく、検査中の取り組み方（行動観察）や生活上の困りごととつなげて解釈することが重要。"},{"id":"binet","t":"田中ビネー知能検査","en":"Tanaka-Binet Intelligence Scale","f":"assess","a":"ビネー（Binet, A.）とシモンが1905年に開発した知能検査を源流とし、日本では田中寛一が標準化した個別式の知能検査で、現行版は田中ビネー知能検査Ⅴである。年齢ごとに配列された問題を用い、2歳から13歳までは精神年齢を求め、それを生活年齢で割って100をかけた比率IQを算出する。14歳以上では偏差IQを用い、領域別の評価も行う。全般的な知的水準を把握しやすく、幼児や知的障害のある人の評価に用いられることが多い。","k":["ビネー/Binet","1905","精神年齢","生活年齢","比率IQ","偏差IQ"],"p":"ウェクスラー式（個人内差・プロフィール）との使い分けを説明できるようにしておく。"},{"id":"battery","t":"テスト・バッテリー","en":"test battery","f":"assess","a":"クライエントを多面的に理解するため、目的に応じて複数の心理検査を組み合わせて実施することをいう。一つの検査でとらえられるのは心の一側面にすぎないため、知能検査と人格検査、意識的な水準をとらえる質問紙法とより深い水準をとらえる投映法などを組み合わせて、相互に補い合う情報を得る。一方で、検査が多すぎるとクライエントの負担が増すため、アセスメントの目的を明確にし、必要最小限の検査を選ぶことが求められる。","k":["複数","多面","質問紙法","投映法","負担","目的"],"p":"「意識水準の異なる検査を組み合わせる」という説明が定番。具体的な組み合わせ例を一つ挙げられると説得力が増す。"},{"id":"bps","t":"生物－心理－社会モデル","en":"biopsychosocial model","f":"assess","a":"精神科医エンゲル（Engel, G. L.）が1977年に、病気を身体の生物学的な異常だけで説明する生物医学モデルを批判して提唱した枠組み。健康や病気を、生物学的要因（遺伝、身体疾患、脳の機能など）、心理的要因（認知、感情、ストレス対処など）、社会的要因（家族、職場、経済状況、文化など）の相互作用からとらえる。心理職がアセスメントを行い、医師、看護師、ソーシャルワーカーなどの多職種と協働するための共通の枠組みとしても重要である。","k":["エンゲル/Engel","1977","生物医学モデル","相互作用","社会的","多職種"],"p":"事例問題の見立てを3つの観点で整理する「型」として使える。"},{"id":"formulation","t":"ケース・フォーミュレーション","en":"case formulation","f":"assess","a":"アセスメントで得られた情報をもとに、クライエントの問題がどのように生じ、なぜ維持されているのかについての仮説を立て、それにもとづいて介入の方針を導く作業をいう。認知行動療法では、きっかけ、認知、感情、行動、身体反応の悪循環として問題を整理することが多く、精神分析的心理療法では、中核的な葛藤や対象関係のパターンとして理解する。フォーミュレーションはクライエントと共有され、介入の結果に応じて修正される仮説である。","k":["仮説","維持","介入","悪循環","共有","修正"],"p":"「なぜ今、この問題が、この形で起きているのか」に答えるもの、と一文で言えると論述の導入に便利。"},{"id":"k-shiki","t":"新版K式発達検査","en":"Kyoto Scale of Psychological Development","f":"assess","a":"京都市児童院（現在の京都市児童福祉センター）で開発された個別式の発達検査で、現行版は新版K式発達検査2020である。0歳から成人までを対象とし、「姿勢・運動」「認知・適応」「言語・社会」の3領域について、検査者が子どもと遊びのように関わりながら、どの課題ができ、どこでつまずくかを観察する。発達年齢と発達指数（DQ）が算出されるが、数値だけでなく、課題への取り組み方などの質的な特徴をとらえることが重視される。","k":["京都","姿勢・運動","認知・適応","言語・社会","発達指数/DQ","質的"],"p":"乳幼児健診後の発達相談などの事例問題で、検査を「子どもの理解と保護者への助言」につなげる流れを書けるように。"},{"id":"screening","t":"認知症のスクリーニング検査","en":"HDS-R / MMSE","f":"assess","a":"認知症の疑いをとらえるために用いられる簡便な検査。改訂長谷川式簡易知能評価スケール（HDS-R）は長谷川和夫が作成し、年齢、日時の見当識、場所、3つの言葉の記銘と遅延再生、計算、数字の逆唱、物品の記銘、言語の流暢性の9問からなり、30点満点中20点以下で認知症が疑われる。MMSEはフォルスタインらが作成し、図形の模写や文の書字などの動作性の課題を含み、30点満点で23点以下が目安とされる。いずれも診断ではなくスクリーニングである。","k":["長谷川和夫","見当識","20点","MMSE","23点","スクリーニング"],"p":"実施時の配慮（自尊心を傷つけない導入、検査の目的の説明）にもふれると臨床的。"},{"id":"feedback","t":"検査結果のフィードバック","en":"feedback of test results","f":"assess","a":"心理検査の結果を、本人や関係者に伝えることをいう。専門用語や数値をそのまま伝えるのではなく、相手が理解でき、生活や支援に活かせる言葉で伝えることが大切である。結果の限界も伝え、レッテル貼りにならないよう、強みや資源にもふれる。フィン（Finn, S. E.）の治療的アセスメントでは、クライエント自身の問いを出発点として検査を行い、結果を協働的に話し合うことで、アセスメントそのものを治療的な体験にすることがめざされる。","k":["本人","理解","限界","強み","フィン/Finn","治療的アセスメント"],"p":"「誰に、何のために、どこまで伝えるか」（本人・保護者・学校・医師）を整理して書くと事例問題に強い。"},{"id":"interview-struct","t":"構造化面接と非構造化面接","en":"structured / unstructured interview","f":"assess","a":"構造化面接は、質問の内容や順序、評価の基準があらかじめ決められている面接で、DSMにもとづく診断のためのSCIDなどがある。面接者による違いが少なく信頼性が高いため、研究や診断に適する。非構造化面接は、質問を固定せず、相手の話の流れに沿って自由に進める面接で、その人に固有の体験や意味を深く理解できるが、面接者の技量に左右されやすい。両者の中間に、主な質問を決めつつ柔軟に掘り下げる半構造化面接があり、質的研究でよく用いられる。","k":["順序","SCID","信頼性","非構造化","半構造化","質的研究"],"p":"研究計画書でインタビュー調査を計画する場合、なぜ半構造化面接を選ぶのかを説明できるようにしておく。"},{"id":"attachment","t":"愛着（アタッチメント）","en":"attachment","f":"hattatsu","a":"ボウルビィ（Bowlby, J.）が提唱した概念で、子どもが不安や危険を感じたときに、特定の養育者に近づき、くっつくことで安心を得ようとする傾向と、それによって結ばれる情緒的な絆をいう。愛着の対象は、子どもにとって不安なときに逃げ込める「安全な避難所」であり、外の世界を探索するための「安全基地」となる。ボウルビィは、施設で育った子どもの研究や動物行動学をもとに、愛着を生存に必要な生物学的な行動システムと考えた。","k":["ボウルビィ/Bowlby","養育者","絆","安全基地","安全な避難所","動物行動学"],"p":"精神分析の「欲動（授乳による満足）」から説明する立場との違い（接触と安心そのものが一次的）を書けると理論史が示せる。"},{"id":"strange-situation","t":"ストレンジ・シチュエーション法","en":"Strange Situation Procedure","f":"hattatsu","a":"エインズワース（Ainsworth, M. D. S.）が考案した、乳児（1歳前後）の愛着の質を評価する実験的な観察法。見知らぬ部屋で、養育者との分離と再会、見知らぬ人との出会いなどの場面を設定し、とくに再会の場面での乳児の行動を観察する。回避型（A型）、安定型（B型）、アンビヴァレント型（C型）に分類され、のちにメイン（Main, M.）らによって、一貫した方略をもたない無秩序・無方向型（D型）が加えられた。D型は虐待などとの関連が指摘されている。","k":["エインズワース/Ainsworth","分離","再会","回避","安定","無秩序"],"p":"「分離のときの泣き方」ではなく「再会のときのふるまい」で分類する点が要。成人愛着面接（AAI）との対応も押さえると強い。"},{"id":"iwm","t":"内的作業モデル","en":"internal working model","f":"hattatsu","a":"ボウルビィが提唱した概念で、子どもが養育者との繰り返しの相互作用を通じて形成する、自己と他者についての心の表象をいう。「困ったときに他者は応えてくれるか」「自分は助けてもらう価値のある存在か」という見通しを含み、その後の対人関係の予測や行動の指針として働く。比較的安定して持続し、成人期の対人関係や子育てにも影響するとされる。ただし、その後の関係の経験によって修正されうるものでもある。","k":["ボウルビィ","相互作用","自己","他者","表象","修正"],"p":"「修正されうる」ことを書くのが重要（心理療法の関係が新しい作業モデルの経験になる、という論点につながる）。"},{"id":"erikson","t":"心理社会的発達理論","en":"psychosocial development theory","f":"hattatsu","a":"エリクソン（Erikson, E. H.）が示した、人間の生涯を8つの段階に分け、各段階で社会との関わりの中で取り組むべき心理社会的危機を対の形で示した理論。乳児期の「基本的信頼 対 不信」から始まり、青年期の「同一性 対 同一性拡散」、成人期の「生殖性（世代性） 対 停滞」、老年期の「統合 対 絶望」へと至る。危機は、肯定的な側面が否定的な側面を上回る形で乗り越えられることで、希望、忠誠、知恵などの人間的な強さが獲得されるとした。","k":["エリクソン/Erikson","8","心理社会的危機","基本的信頼","同一性","統合"],"p":"「否定的な側面もなくてはならない（比率の問題）」という点を書けると正確。フロイトの心理性的発達論との違い（社会との関わり、生涯発達）も押さえる。"},{"id":"identity","t":"アイデンティティ（自我同一性）","en":"ego identity","f":"hattatsu","a":"エリクソンが青年期の発達課題とした概念で、「自分は自分である」という斉一性と、過去から未来へと続いている連続性の感覚をもち、それが他者や社会からも認められているという感覚をいう。青年期には、社会的な責任や義務の遂行を猶予されたモラトリアムの中で、さまざまな役割を試しながら自分を模索する。これが達成されないと、自分が何者かわからない同一性拡散の状態に陥る。マーシャはこれを、危機と傾倒の有無から4つの同一性地位に分類した。","k":["エリクソン","斉一性","連続性","モラトリアム","同一性拡散","マーシャ/Marcia"],"p":"マーシャの4地位（達成・モラトリアム・早期完了・拡散）を、危機と傾倒の2軸で表にできるようにしておく。"},{"id":"piaget","t":"ピアジェの認知発達段階","en":"Piaget's stages","f":"hattatsu","a":"ピアジェ（Piaget, J.）は、子どもが外界と関わりながら、既存の認知の枠組み（シェマ）に取り込む同化と、シェマ自体を変える調節を通じて認知を発達させると考えた。発達は、感覚と運動を通じて世界を知る感覚運動期（0〜2歳）、表象や言語が発達するが自己中心性の強い前操作期（2〜7歳）、具体物について論理的に考えられる具体的操作期（7〜11歳）、抽象的・仮説的な思考が可能になる形式的操作期（11歳以降）の4段階を経る。","k":["ピアジェ/Piaget","同化","調節","感覚運動期","前操作期","形式的操作期"],"p":"ヴィゴツキー（社会的相互作用を重視）との比較が定番。子どもの年齢に応じた説明（プレパレーション）の根拠にも使える。"},{"id":"zpd","t":"発達の最近接領域","en":"zone of proximal development","f":"hattatsu","a":"ヴィゴツキー（Vygotsky, L. S.）が提唱した概念で、子どもが自分一人で解決できる水準と、大人や能力のある仲間の援助があれば解決できる水準との間の領域をいう。教育は、すでに完成した発達に合わせるのではなく、この領域に働きかけることで発達を先導すべきだとした。のちにブルーナーらは、援助者が必要に応じて支え、できるようになるにつれて徐々に支えを外していく関わりを「足場かけ」と呼んだ。社会的な相互作用が発達の源であるという考えにもとづく。","k":["ヴィゴツキー/Vygotsky","一人","援助","足場かけ","社会的","相互作用"],"p":"ピアジェ（個人が構成する）との対比で「社会から個人へ」という方向性を書ける。"},{"id":"tom","t":"心の理論","en":"theory of mind","f":"hattatsu","a":"他者にも自分とは異なる意図、信念、欲求などの心の状態があることを理解し、それにもとづいて他者の行動を予測したり説明したりする能力をいう。プレマック（Premack, D.）とウッドラフが、チンパンジーの研究の中で用いた言葉である。誤った信念（誤信念）を理解できるかを調べる課題（サリーとアンの課題など）を用いた研究から、定型発達の子どもでは、おおむね4歳ごろに通過できるようになることが示された。自閉スペクトラム症の理解をめぐっても研究が進められた。","k":["心の状態","プレマック/Premack","誤信念","サリー","4歳","自閉"],"p":"「自閉スペクトラム症＝心の理論の欠如」と単純化しない（言語や課題の性質の影響、近年の議論）こと。"},{"id":"mahler","t":"分離－個体化","en":"separation-individuation","f":"hattatsu","a":"マーラー（Mahler, M. S.）が乳幼児の観察研究から示した、子どもが母親との心理的な一体感から抜け出し、独立した個としての自己を確立していく過程。共生期に続く分離－個体化期は、分化期、練習期、再接近期、個体化の確立と情緒的対象恒常性の始まりの4つの下位段階からなる。とくに再接近期には、離れたい気持ちと母親に頼りたい気持ちの間で揺れ動く危機（再接近期危機）が生じ、境界性パーソナリティの病理との関連が論じられた。","k":["マーラー/Mahler","一体感","共生","練習期","再接近期","対象恒常性"],"p":"青年期の「第二の分離－個体化」（ブロス）とセットで覚える。"},{"id":"temperament","t":"気質","en":"temperament","f":"hattatsu","a":"生まれつき備わり、比較的早期から現れる、刺激への反応の仕方や行動の個人差をいう。トマス（Thomas, A.）とチェス（Chess, S.）はニューヨーク縦断研究で、活動水準、周期性、順応性などの9つの次元から、扱いやすい子、扱いにくい子、出だしの遅い子という類型を見いだした。そして、子どもの気質と、親や環境の要求や期待とが合っているか（適合のよさ）が、その後の適応に影響すると考えた。気質は、環境との相互作用の中で性格へと発達していく。","k":["生まれつき","トマス/Thomas","9つ","扱いにくい","適合のよさ","相互作用"],"p":"「親の育て方が悪い」でも「生まれつきで変わらない」でもない、相互作用の視点を書くことが要点。"},{"id":"lifespan","t":"生涯発達とSOC理論","en":"life-span development / SOC","f":"hattatsu","a":"発達を、子どもが大人になるまでの成長に限らず、受精から死に至るまでの生涯にわたる獲得と喪失の過程ととらえる考え方。バルテス（Baltes, P. B.）は、加齢によって資源が限られていく中で、目標を絞り込む選択、残された資源を集中させる最適化、失われた機能を他の手段で補う補償を組み合わせることで、高齢者は適応を保つとした（補償を伴う選択的最適化：SOC理論）。カーステンセンの社会情動的選択性理論も、老年期の適応を説明する理論として知られる。","k":["生涯","喪失","バルテス/Baltes","選択","最適化","補償"],"p":"ピアニストのルービンシュタインの例（曲を絞り、練習を重ね、速さの対比を工夫する）がよく紹介される。"},{"id":"blos","t":"第二の分離－個体化","en":"second individuation","f":"hattatsu","a":"ブロス（Blos, P.）が、マーラーの分離－個体化の考えを青年期に当てはめて論じたもの。青年は、児童期まで内在化していた親のイメージや、親への依存から心理的に離脱し、自分自身の価値観やアイデンティティを形成していく。その過程では、親への反抗や、理想化された仲間への傾倒、一時的な退行などがみられ、不安定さを伴う。この時期の揺れ動きは正常な発達の過程でもあり、親や周囲の大人には、離れていく子どもを見守りつつ支える関わりが求められる。","k":["ブロス/Blos","青年期","親","依存","反抗","退行"],"p":"思春期の事例（反抗、家庭内暴力、不登校）で、症状の「発達的な意味」を考える視点として使える。"},{"id":"abuse","t":"児童虐待","en":"child abuse","f":"hattatsu","a":"保護者がその監護する児童に対して行う、身体的虐待、性的虐待、ネグレクト（養育の放棄・怠慢）、心理的虐待の4類型をいう（児童虐待防止法、2000年）。子どもの前で家族に暴力をふるう面前DVも、心理的虐待に含まれる。虐待を受けたと思われる児童を発見した者には、通告の義務がある。虐待は子どもの心身の発達に深刻な影響を与え、愛着の問題や複雑性トラウマにもつながる。支援では子どもの安全確保を最優先とし、多機関の連携による家族への支援が求められる。","k":["身体的虐待","性的虐待","ネグレクト","心理的虐待","面前DV","通告"],"p":"通告義務は守秘義務より優先される（守秘義務違反にならない）ことを、倫理の論述でも使えるようにしておく。"},{"id":"futoko","t":"不登校","en":"school non-attendance","f":"hattatsu","a":"文部科学省は、何らかの心理的、情緒的、身体的、あるいは社会的な要因・背景により、登校しない、あるいはしたくともできない状況にあるために、年間30日以上欠席した者のうち、病気や経済的な理由によるものを除いたものと定義している。背景は多様で、一つの原因に帰することは難しい。教育機会確保法（2016年）では、学校以外の場での多様な学びの重要性や、休養の必要性も認められた。学校への復帰だけを目標とせず、子どもの社会的な自立を支える視点が求められる。","k":["文部科学省","30日","心理的","多様","教育機会確保法","自立"],"p":"不登校を「問題行動」と見なさないという国の方針の変化（2016年以降）にふれると、知識の新しさを示せる。"},{"id":"bullying","t":"いじめ","en":"bullying","f":"hattatsu","a":"いじめ防止対策推進法（2013年）では、児童等に対して、一定の人的関係にある他の児童等が行う心理的または物理的な影響を与える行為（インターネットを通じて行われるものを含む）であって、その対象となった児童等が心身の苦痛を感じているものと定義される。被害者の主観を重視する定義であり、学校には、いじめ防止のための組織の設置や、重大事態への対処が義務づけられた。スクールカウンセラーには、被害を受けた子どもの支援とともに、加害や傍観の背景の理解も求められる。","k":["いじめ防止対策推進法","2013","心身の苦痛","インターネット","重大事態","スクールカウンセラー"],"p":"「加害者を罰する」だけでなく、学級集団（観衆・傍観者）への働きかけの視点を入れると、コミュニティ心理学的な答案になる。"},{"id":"secondary-dd","t":"発達障害の二次障害","en":"secondary problems","f":"hattatsu","a":"発達障害のある人が、特性そのものによる困難ではなく、特性が周囲に理解されないまま叱責や失敗、いじめなどを繰り返し経験することによって、二次的に生じる問題をいう。自己評価の低下、抑うつ、不安、不登校やひきこもりといった内在化の問題と、反抗、暴力、非行などの外在化の問題がある。早期に特性に気づき、環境を調整し、本人の強みを活かした成功体験を積み重ねられるよう支えることが、二次障害の予防につながる。","k":["特性","理解","自己評価","抑うつ","外在化","環境"],"p":"成人期になって初めて気づかれる発達特性と、うつ・不安などの二次的な問題という論点も押さえておく。"},{"id":"family-lc","t":"家族ライフサイクル","en":"family life cycle","f":"hattatsu","a":"家族を、結婚による家族の成立、子どもの誕生と養育、子どもの思春期、子どもの巣立ち、老年期と、時間とともに発達していくシステムとしてとらえる考え方。カーター（Carter, B.）とマクゴールドリック（McGoldrick, M.）らは、各段階に家族が取り組む発達課題があり、段階の移行期には家族の関係の組み直しが必要となるため、ストレスや症状が生じやすいと考えた。個人の問題を、家族の発達の文脈の中で理解するための視点として、家族療法で用いられる。","k":["家族","段階","カーター/マクゴールドリック","発達課題","移行期","家族療法"],"p":"「なぜ今この時期に症状が出たのか」を、家族の移行期と結びつけて考える視点として事例問題に使える。"},{"id":"rad","t":"アタッチメントの障害","en":"attachment disorders","f":"hattatsu","a":"DSM-5では、極端に不十分な養育（ネグレクトや養育者の頻繁な交代など）を経験した子どもにみられる障害として、反応性アタッチメント障害と脱抑制型対人交流障害が示されている。前者は、苦痛なときにも養育者に慰めを求めず、感情の表出が乏しいなど、愛着行動が抑制された状態をいう。後者は、見知らぬ大人にもためらいなく近づき、ついて行こうとするなど、過度になれなれしい行動を特徴とする。安定した養育環境の確保と、養育者との関係の支援が重要である。","k":["不十分な養育/ネグレクト","反応性アタッチメント障害","脱抑制型対人交流障害","慰め","見知らぬ","養育環境"],"p":"自閉スペクトラム症との鑑別（養育歴の確認）が論点になる。社会的養護（児童養護施設・里親）の文脈とも結びつけられる。"},{"id":"classical","t":"古典的条件づけ","en":"classical conditioning","f":"kiso","a":"パヴロフ（Pavlov, I. P.）がイヌの唾液分泌の研究から見いだした学習の過程で、レスポンデント条件づけとも呼ばれる。もともと反応（無条件反応）を引き起こす無条件刺激（餌）と、中性刺激（メトロノームの音など）を対にして繰り返し提示すると、中性刺激だけで反応が生じるようになる。このとき中性刺激は条件刺激、生じる反応は条件反応となる。条件刺激だけを提示し続けると反応は弱まる（消去）。恐怖症の成り立ちの説明や、エクスポージャーなどの治療の基盤となった。","k":["パヴロフ/Pavlov","無条件刺激","条件刺激","条件反応","消去","恐怖症"],"p":"ワトソンの「アルバート坊やの実験」（恐怖の条件づけ）とその倫理的問題もあわせて押さえる。"},{"id":"operant","t":"オペラント条件づけ","en":"operant conditioning","f":"kiso","a":"スキナー（Skinner, B. F.）が体系化した学習の原理で、自発的な行動（オペラント）が、その直後に生じる結果によって増えたり減ったりする過程をいう。行動の後によいことが生じる、または嫌なことがなくなることで行動が増えることを強化、行動の後に嫌なことが生じる、またはよいことがなくなることで行動が減ることを罰という。行動に先立つ状況（先行事象）、行動、結果の関係を分析する応用行動分析として、教育や臨床、発達障害の支援に広く応用されている。","k":["スキナー/Skinner","自発","結果","強化","罰","応用行動分析"],"p":"「正の／負の」と「強化／罰」の4つの組み合わせを例で説明できるようにしておく（負の強化を罰と混同しない）。"},{"id":"learned-helplessness","t":"学習性無力感","en":"learned helplessness","f":"kiso","a":"セリグマン（Seligman, M. E. P.）らが動物実験で見いだした現象で、自分の行動によっては不快な状況を避けられない（統制できない）経験を繰り返すと、その後、逃れることが可能な状況になっても、逃れようとしなくなることをいう。その後、人間については、失敗の原因を内的で、安定的で、全般的なものに帰属する傾向が無力感や抑うつにつながるという改訂理論が示され、うつ病の心理学的なモデルの一つとなった。","k":["セリグマン/Seligman","統制","逃れ","帰属","抑うつ","内的"],"p":"虐待やDVの被害者が「逃げない」ことの理解に用いられることがあるが、本人の責任に帰さない書き方を心がける。"},{"id":"modeling","t":"観察学習（モデリング）","en":"observational learning","f":"kiso","a":"バンデューラ（Bandura, A.）が示した学習の形態で、自分が直接に経験したり強化を受けたりしなくても、他者（モデル）の行動とその結果を観察するだけで、新しい行動を学習することをいう。大人がビニール人形に攻撃的にふるまう映像を見た子どもが、同じような攻撃行動をとったボボ人形の実験が知られる。注意、保持、運動再生、動機づけの過程からなる。他者が報酬を受ける様子を見ることを代理強化という。社会的学習理論の中心的な概念である。","k":["バンデューラ/Bandura","観察","ボボ人形","代理強化","社会的学習理論","注意"],"p":"SST（社会生活スキルトレーニング）でのモデリングの活用など、臨床への応用例を一つ添える。"},{"id":"self-efficacy","t":"自己効力感","en":"self-efficacy","f":"kiso","a":"バンデューラが提唱した概念で、ある結果を得るために必要な行動を、自分がうまく行うことができるという確信をいう。行動すればその結果が得られるという結果予期とは区別され、自己効力感（効力予期）が高いほど、人はその行動に取り組み、困難があっても粘り強く続けるとされる。自己効力感は、自分で達成した経験（遂行行動の達成）、他者の成功を見る代理経験、言語的説得、生理的・情動的な状態の4つの情報源によって高められる。","k":["バンデューラ/Bandura","確信","結果予期","遂行行動の達成/成功体験","代理経験","言語的説得"],"p":"「自己肯定感」「自尊感情」との違い（特定の行動についての見通し）を明確にする。"},{"id":"attribution","t":"原因帰属","en":"causal attribution","f":"kiso","a":"自分や他者の行動、出来事の原因を推論することをいい、ハイダー（Heider, F.）は、本人の能力や性格などの内的な要因に原因を求める場合と、状況などの外的な要因に求める場合を区別した。人は他者の行動の原因を考えるとき、状況の影響を軽視し、その人の内的な特性に原因を求めやすい傾向があり、これを基本的な帰属の誤りという。また、自分の成功は内的な要因に、失敗は外的な要因に帰属しやすい傾向（自己奉仕的バイアス）もある。","k":["原因","ハイダー/Heider","内的","外的","状況","自己奉仕的バイアス"],"p":"支援者がクライエントの行動を「性格のせい」と見なしやすい（基本的な帰属の誤り）ことへの自戒として論じることもできる。"},{"id":"dissonance","t":"認知的不協和","en":"cognitive dissonance","f":"kiso","a":"フェスティンガー（Festinger, L.）が1957年に提唱した理論で、人が自分の中に互いに矛盾する認知（考え、信念、行動についての知識など）を同時に抱えると、不快な緊張状態（不協和）が生じ、それを低減しようとして、認知や行動を変えたり、新たな認知を加えたりすることをいう。退屈な作業をした後に、わずかな報酬でその作業は面白かったと他者に伝えた人ほど、作業を面白いと評価するようになった実験が知られる。態度変容や自己正当化の理解に用いられる。","k":["フェスティンガー/Festinger","1957","矛盾","不快","低減","報酬"],"p":"動機づけ面接で、本人の価値と現在の行動との「ずれ」を広げる技法と関連づけることもできる。"},{"id":"working-memory","t":"ワーキングメモリ","en":"working memory","f":"kiso","a":"バドリー（Baddeley, A. D.）とヒッチ（Hitch, G. J.）が1974年に提唱した、情報を一時的に保持しながら、同時にそれを操作・処理するための記憶のシステム。単に情報を貯蔵する短期記憶の概念を発展させたもので、注意を制御する中央実行系と、言語的な情報を保持する音韻ループ、視覚的・空間的な情報を保持する視空間スケッチパッド、さらに後に加えられたエピソード・バッファからなる。読み書きや計算、推論などの基盤となり、発達障害の理解にも用いられる。","k":["バドリー/Baddeley","1974","保持","中央実行系","音韻ループ","視空間スケッチパッド"],"p":"WAIS-IVのワーキングメモリー指標とつなげて、学習面の支援（指示を短く区切る等）に結びつけると臨床的。"},{"id":"memory-types","t":"長期記憶の分類","en":"types of long-term memory","f":"kiso","a":"長期記憶は、言葉やイメージとして意識的に想起できる宣言的記憶（顕在記憶）と、意識的な想起を伴わない非宣言的記憶（潜在記憶）に大きく分けられる。宣言的記憶はさらに、タルヴィング（Tulving, E.）によって、「いつ、どこで」という個人の経験に関するエピソード記憶と、一般的な知識である意味記憶に区別された。非宣言的記憶には、自転車の乗り方などの手続き記憶や、先行する刺激が後の処理に影響するプライミングなどが含まれる。","k":["宣言的記憶","非宣言的記憶","タルヴィング/Tulving","エピソード記憶","意味記憶","手続き記憶"],"p":"認知症ではエピソード記憶が早く障害され、手続き記憶は比較的保たれやすい、という臨床的な対応づけができると強い。"},{"id":"coping","t":"ストレス・コーピング","en":"stress coping","f":"kiso","a":"ラザルス（Lazarus, R. S.）とフォルクマン（Folkman, S.）の心理学的ストレス理論では、ストレスは出来事そのものではなく、人と環境との相互作用の中で生じるとされる。出来事が自分にとって脅威かどうかを判断する一次的評価と、それに対処できるかを判断する二次的評価を経て、対処（コーピング）が行われる。問題そのものの解決をめざす問題焦点型コーピングと、それに伴う感情の調整をめざす情動焦点型コーピングがあり、状況に応じた使い分けが重要である。","k":["ラザルス/Lazarus","相互作用","一次的評価","二次的評価","問題焦点","情動焦点"],"p":"「問題焦点型がよい」と単純化しない（変えられない状況では情動焦点型が適応的）ことを書く。"},{"id":"emotion-theory","t":"情動の理論","en":"theories of emotion","f":"kiso","a":"ジェームズ＝ランゲ説は、刺激によって身体の生理的な変化が生じ、その変化の知覚が情動の体験になると考えた（「泣くから悲しい」）。キャノン＝バード説はこれを批判し、刺激の情報が視床で処理され、大脳皮質での情動の体験と身体の反応が同時に生じるとした。シャクター（Schachter, S.）とシンガーの2要因説は、生理的な覚醒と、その覚醒の原因についての認知的な解釈（ラベルづけ）の両方によって情動が決まるとした。","k":["ジェームズ/ランゲ","身体","キャノン/バード","視床","シャクター/Schachter","2要因"],"p":"3説を「身体→情動」「同時」「覚醒＋認知」と一言で区別できるように。"},{"id":"sdt","t":"自己決定理論と内発的動機づけ","en":"self-determination theory","f":"kiso","a":"内発的動機づけとは、報酬や罰などの外からの働きかけではなく、活動そのものへの興味や楽しさによって行動が引き起こされることをいう。デシ（Deci, E. L.）は、内発的に取り組んでいる活動に外的な報酬を与えると、かえって内発的動機づけが低下するアンダーマイニング効果を示した。デシとライアンの自己決定理論は、自律性、有能感、関係性の3つの基本的な心理的欲求が満たされることで、動機づけが内在化され、人は健康に成長すると考える。","k":["内発的動機づけ","デシ/Deci","アンダーマイニング","自律性","有能感","関係性"],"p":"外発的動機づけも段階的に内在化しうる（取り入れ・同一化・統合）点まで書けると正確。"},{"id":"big5","t":"特性5因子論（ビッグファイブ）","en":"Big Five","f":"kiso","a":"パーソナリティを少数の基本的な特性の組み合わせで記述する特性論のモデルで、多くの研究で共通して見いだされた5つの因子からなる。神経症傾向（情緒不安定性）、外向性、開放性（経験への開放性）、調和性（協調性）、誠実性（勤勉性）である。辞書から人格を表す言葉を集めて分析する語彙研究と、質問紙研究の両方から支持され、文化を越えた一貫性も示されている。性格を類型に分ける類型論に対し、程度の違いで連続的に記述する点に特徴がある。","k":["特性論","神経症傾向","外向性","開放性","調和性","誠実性"],"p":"ユングのタイプ論（類型論）との比較で問われうる。因子分析という研究法とも結びつけられる。"},{"id":"bystander","t":"傍観者効果","en":"bystander effect","f":"kiso","a":"緊急事態の場面で、その場に居合わせる人が多いほど、一人ひとりが援助行動をとりにくくなる現象をいう。ラタネ（Latané, B.）とダーリー（Darley, J. M.）が、ニューヨークで起きた殺人事件の報道をきっかけに実験的に研究した。その背景には、他の人が助けるだろうと考える責任の分散、他の人が動かないことから事態を深刻でないと判断する多元的無知、人前で失敗することへの懸念（評価懸念）がある。具体的な人を名指しして援助を求めることが有効とされる。","k":["援助","ラタネ/Latane","ダーリー","責任の分散","多元的無知","評価懸念"],"p":"いじめの「傍観者」の理解や、自殺予防のゲートキーパーの考え方につなげられる。"},{"id":"conformity","t":"同調と服従","en":"conformity / obedience","f":"kiso","a":"同調とは、集団の圧力によって、個人が意見や行動を集団の多数派に合わせることをいう。アッシュ（Asch, S. E.）は、明らかに誤った答えを述べるサクラの多数派の中で、実験参加者の判断の誤りが増えることを示した。服従とは、権威者の命令に従うことをいい、ミルグラム（Milgram, S.）の実験では、多くの参加者が実験者の指示に従って、他者に強い電気ショックを与え続けた（と信じた）。人の行動が状況の力に大きく左右されることを示すとともに、研究倫理の議論も呼んだ。","k":["同調","アッシュ/Asch","多数派","服従","ミルグラム/Milgram","研究倫理"],"p":"研究倫理（欺瞞、参加者の苦痛、デブリーフィング）の論述の具体例としても使える。"},{"id":"social-support","t":"ソーシャル・サポート","en":"social support","f":"kiso","a":"家族、友人、同僚、専門家など、人をとりまく周囲の人々から得られる有形・無形の支援をいう。気持ちを受け止める情緒的サポート、具体的な手助けや物の提供である道具的サポート、問題の解決に役立つ情報を与える情報的サポート、行動や考えを認める評価的サポートなどに分けられる。ストレスの有無にかかわらず健康によい影響を与える直接効果と、強いストレスにさらされたときにその悪影響を和らげる緩衝効果があるとされる。","k":["周囲","情緒的","道具的","情報的","直接効果","緩衝効果"],"p":"研究計画書で「援助要請」「孤独感」などを扱う場合の基礎概念。受け手が「サポートと感じるか」（知覚されたサポート）の重要性にもふれられるとよい。"},{"id":"metacognition","t":"メタ認知","en":"metacognition","f":"kiso","a":"フラベル（Flavell, J. H.）が提唱した概念で、自分の認知（知覚、記憶、思考など）を一段上から認知すること、すなわち「認知についての認知」をいう。自分や課題、方略についての知識であるメタ認知的知識と、自分の認知の状態をモニタリングし、必要に応じてコントロールするメタ認知的活動からなる。学習の場面では、理解の程度を自己点検し、方略を調整する力として重要である。臨床でも、思考を事実としてではなく思考として眺める力として、認知行動療法などで注目されている。","k":["フラベル/Flavell","認知についての認知","メタ認知的知識","モニタリング","コントロール","方略"],"p":"マインドフルネスやメンタライゼーションと関連づけて、「自分の心を眺める力」という共通の軸で論じることができる。"},{"id":"hpa","t":"ストレス反応とHPA軸","en":"stress response / HPA axis","f":"kiso","a":"ストレッサーにさらされると、視床下部から副腎皮質刺激ホルモン放出ホルモン（CRH）が分泌され、それが下垂体からの副腎皮質刺激ホルモン（ACTH）の分泌を促し、副腎皮質からコルチゾールが分泌される。この経路を視床下部－下垂体－副腎皮質系（HPA軸）という。また交感神経－副腎髄質系も働き、心拍数や血圧が上がる。セリエ（Selye, H.）は、ストレスへの非特異的な反応の経過を、警告反応期、抵抗期、疲憊期からなる汎適応症候群として示した。","k":["視床下部","下垂体","コルチゾール","交感神経","セリエ/Selye","汎適応症候群"],"p":"生物－心理－社会モデルの「生物」の側面として、慢性ストレスが心身に与える影響を説明する際に使える。"},{"id":"reliability","t":"信頼性","en":"reliability","f":"kenkyu","a":"測定が、同じ対象に対して一貫した安定した結果を示す程度をいう。同じ人に時間をおいて同じ検査を行い、得点の相関を調べる再検査法、検査項目を2つに分けて得点の相関を調べる折半法、項目間の一貫性を示すクロンバックのα係数などで評価される。評定者が複数いる場合には、評定者間の一致度も検討される。信頼性は妥当性の必要条件であり、信頼性の低い測定からは妥当な結論は得られないが、信頼性が高いからといって妥当性が保証されるわけではない。","k":["一貫","再検査法","折半法","α係数/クロンバック","評定者間","妥当性"],"p":"「信頼性は妥当性の必要条件であって十分条件ではない」は定番の締めの一文。的当ての比喩で説明してもよい。"},{"id":"validity","t":"妥当性","en":"validity","f":"kenkyu","a":"測定しようとしている概念を、その測定が実際にどの程度正しくとらえているかをいう。項目がその概念の内容を適切に代表しているかという内容的妥当性、外的な基準との関連による基準関連妥当性（併存的妥当性、予測的妥当性）、理論的に予測される他の変数との関係が示されるかという構成概念妥当性（関連すべき変数とは関連する収束的妥当性、関連すべきでない変数とは関連しない弁別的妥当性）がある。近年は、構成概念妥当性を中心とする統一的な見方が主流である。","k":["測定","内容的妥当性","基準関連妥当性","予測的/併存的","構成概念妥当性","収束的"],"p":"研究計画書で既存の尺度を使う場合、「信頼性・妥当性が確認された尺度を用いる」と書き、その根拠（原著論文）を示すことが求められる。"},{"id":"int-ext-validity","t":"内的妥当性と外的妥当性","en":"internal / external validity","f":"kenkyu","a":"キャンベル（Campbell, D. T.）らが整理した研究の妥当性の概念。内的妥当性とは、研究で観察された結果が、本当に独立変数の操作によるものであり、他の要因によるものではないといえる程度をいう。履歴、成熟、テスト効果、統計的な平均への回帰、参加者の選択や脱落などがこれを脅かす。外的妥当性とは、研究の結果を、他の対象者、場面、時期などにどの程度一般化できるかをいう。厳密な統制は内的妥当性を高めるが、外的妥当性を損なうことがある。","k":["キャンベル/Campbell","独立変数","他の要因","平均への回帰","一般化","統制"],"p":"RCTと事例研究の長所・短所を、この2つの妥当性で整理すると論述の骨格になる。"},{"id":"rct","t":"ランダム化比較試験（RCT）","en":"randomized controlled trial","f":"kenkyu","a":"研究の参加者を無作為に介入群と対照群（待機群、通常治療群など）に割り付け、両群の結果を比較することで、介入の効果を検証する研究デザイン。無作為な割り付けにより、測定されていない要因も含めて群間の偏りが確率的にならされるため、因果関係の推論に適し、効果研究において最も質の高いデザインの一つとされる。一方で、厳密に選ばれた対象者や手続きのもとでの結果が、実際の臨床現場にそのまま当てはまるとは限らないという外的妥当性の問題がある。","k":["無作為/ランダム","割り付け","対照群","因果","偏り","外的妥当性"],"p":"心理療法では二重盲検が困難であること、効能（efficacy）と実地での効果（effectiveness）の区別も添えると深い。"},{"id":"meta-analysis","t":"メタ分析","en":"meta-analysis","f":"kenkyu","a":"同じテーマについての複数の独立した研究の結果を、効果量などの共通の指標に変換して統計的に統合し、全体としての効果の大きさや一貫性を検討する方法。グラス（Glass, G. V.）が名づけ、スミスとグラスによる心理療法の効果のメタ分析が知られる。個々の研究の検定力の不足を補い、研究間の違いを生む要因も検討できる。一方で、有意な結果の研究ほど公表されやすいという出版バイアスや、質の異なる研究を混ぜてしまう問題に注意が必要である。","k":["複数","効果量","統合","グラス/Glass","心理療法","出版バイアス"],"p":"アイゼンクの「心理療法は効果がない」という批判（1952年）に対する応答として、メタ分析が果たした歴史的な役割を書ける。"},{"id":"effect-size","t":"効果量","en":"effect size","f":"kenkyu","a":"効果や差、関連の大きさを、標本の大きさに左右されない形で示す指標。2群の平均値の差を標準偏差で割ったコーエンのd、相関係数r、分散分析での説明率η²などがある。コーエンは、dについて0.2を小、0.5を中、0.8を大の目安とした。p値は、標本が大きければ小さな差でも有意になるため、効果が実質的に意味のある大きさかを判断するには、効果量とその信頼区間を報告することが求められる。メタ分析や検定力分析の基礎ともなる。","k":["大きさ","標本","コーエン/Cohen","0.5","p値","信頼区間"],"p":"「有意＝効果が大きい」ではない、という誤解を正せるかが問われる。"},{"id":"nhst","t":"統計的仮説検定と2種類の誤り","en":"significance testing / Type I and II errors","f":"kenkyu","a":"統計的仮説検定では、差や関連がないという帰無仮説を立て、それが正しいと仮定したときに、得られたデータと同じかそれ以上に極端な結果が生じる確率（p値）を求め、それが有意水準（通常は5％）を下回れば帰無仮説を棄却する。帰無仮説が正しいのに誤って棄却する誤りを第1種の誤り（α）、帰無仮説が誤っているのに棄却しない誤りを第2種の誤り（β）という。p値は効果の大きさや、仮説が正しい確率を示すものではない点に注意が必要である。","k":["帰無仮説","p値","有意水準","第1種","第2種","棄却"],"p":"多重比較で第1種の誤りが増える問題（ボンフェローニ補正など）まで書けると一段上。"},{"id":"power","t":"検定力","en":"statistical power","f":"kenkyu","a":"帰無仮説が誤っているときに、それを正しく棄却できる確率をいい、1から第2種の誤りの確率（β）を引いた値で表される。検定力は、効果量、標本の大きさ、有意水準によって決まり、一般に0.8以上が望ましいとされる。検定力の低い研究では、本当は効果があっても見逃しやすく、また有意になった結果は効果を過大に見積もっている可能性が高い。研究を計画する段階で、想定される効果量から必要な標本の大きさを求めておくこと（検定力分析）が求められる。","k":["棄却","第2種","効果量","標本","0.8","検定力分析"],"p":"研究計画書で「対象者○名」とする根拠として、検定力分析にふれられると評価が高い。"},{"id":"confounding","t":"交絡と擬似相関","en":"confounding / spurious correlation","f":"kenkyu","a":"交絡とは、注目している原因と結果の両方に影響する第三の変数（交絡変数）があるために、両者の関係が実際とは異なって見えることをいう。たとえば、アイスクリームの売上と水難事故の件数に相関があっても、両者は気温という第三の変数の影響を受けているにすぎず、因果関係はない。このような見かけ上の相関を擬似相関という。相関関係は因果関係を意味しないため、無作為化、統制、層別化や統計的な調整によって交絡を取り除く工夫が必要となる。","k":["第三の変数","交絡変数","擬似相関","因果","無作為化","統計的な調整"],"p":"「逆の因果」（結果が原因に影響している可能性）もあわせて書くと、相関研究の解釈の論述として完成度が上がる。"},{"id":"single-case","t":"単一事例実験デザイン","en":"single-case experimental design","f":"kenkyu","a":"一人または少数の対象者について、標的となる行動などを繰り返し測定し、介入の有無による変化を比べることで、介入の効果を検証する研究デザイン。介入前のベースライン期（A）と介入期（B）を設け、介入を除去して再びベースラインに戻すABAデザインやABABデザイン、複数の行動・場面・対象者で時期をずらして介入を始める多層ベースライン・デザインなどがある。個別の臨床実践と効果の検証を結びつける方法として、応用行動分析などで用いられる。","k":["繰り返し","ベースライン","ABA","多層ベースライン","個別","応用行動分析"],"p":"介入の除去が倫理的に問題となる場合に多層ベースラインが選ばれる、という理由づけまで書く。"},{"id":"case-study","t":"事例研究","en":"case study","f":"kenkyu","a":"一つまたは少数の事例について、その経過を詳しく記述し、検討することで、事例の理解を深め、臨床的な知見や仮説を導く研究法。心理臨床では、フロイトの症例研究以来、理論や技法の発展を支えてきた。個別性や文脈、治療関係の中での変化の過程を豊かにとらえられる一方、一般化には限界があり、記述が研究者の主観に偏る危険もある。そのため、考察の根拠を明示すること、他の事例や研究と照らし合わせること、プライバシーの保護に十分配慮することが求められる。","k":["少数","経過","フロイト","個別性","一般化","プライバシー"],"p":"「一般化」には統計的な一般化だけでなく、読み手が自分の臨床に照らして意味を見いだす「臨床的な一般化」もある、という論点が使える。"},{"id":"qualitative","t":"質的研究","en":"qualitative research","f":"kenkyu","a":"インタビューや観察、記録などから得られる言語的なデータを、数量化せずに分析し、人々の体験やその意味、現象が生じる過程を理解しようとする研究法の総称。データにもとづいて理論を生成するグラウンデッド・セオリー・アプローチ（グレイザーとストラウス。修正版のM-GTAは木下康仁）、KJ法、複線径路等至性アプローチ（TEA）、解釈的現象学的分析（IPA）などがある。研究者自身の立場や影響を自覚する省察性（リフレクシヴィティ）と、分析手続きの透明性が重視される。","k":["インタビュー","意味","グラウンデッド・セオリー/GTA","KJ法","IPA/解釈的現象学的分析","リフレクシヴィティ/省察性"],"p":"研究計画書で質的研究を選ぶ場合、「なぜ量的でなく質的か」（未知の現象の探索、過程や意味の理解）を必ず説明する。"},{"id":"mixed","t":"混合研究法","en":"mixed methods research","f":"kenkyu","a":"同じ研究の中で量的研究と質的研究を組み合わせ、それぞれの長所を活かして、一つの問いにより深く答えようとする研究法。量的データと質的データを同時に集めて比べる収斂デザイン、量的研究の結果を質的研究で説明する説明的順次デザイン、質的研究で探索した結果をもとに尺度などを作って量的に検証する探索的順次デザインなどがある（クレスウェル）。両者をどの段階でどのように統合するかを、研究の目的に応じて明確にすることが求められる。","k":["量的","質的","収斂","説明的順次","探索的順次","統合"],"p":"修士の2年間で無理なく実施できる規模か、という実現可能性の観点も忘れずに。"},{"id":"factor-analysis","t":"因子分析","en":"factor analysis","f":"kenkyu","a":"多数の観測変数の間の相関関係を、それらに共通して影響する少数の潜在的な変数（因子）によって説明しようとする多変量解析の方法。心理尺度の作成で、項目がどのようなまとまりをもつかを調べるために用いられる。データから因子の構造を探る探索的因子分析と、仮説として設定した因子構造がデータに合うかを検証する確認的因子分析がある。探索的因子分析では、因子の数の決定や、解釈しやすくするための因子軸の回転（直交回転、斜交回転）が重要となる。","k":["相関","潜在","因子","探索的","確認的","回転"],"p":"主成分分析との違い（因子分析は潜在変数を仮定する）を問われることがある。"},{"id":"longitudinal","t":"横断研究と縦断研究","en":"cross-sectional / longitudinal study","f":"kenkyu","a":"発達的な変化を調べる研究法。横断研究は、異なる年齢の人々を同じ時期に調べて比較する方法で、短期間で多くのデータが得られるが、年齢による差に、生まれた時代の違いによる影響（コホート効果）が混じる。縦断研究は、同じ人々を長期間にわたって追跡して調べる方法で、個人内の変化や、早期の要因が後の状態に与える影響を検討できるが、時間と費用がかかり、参加者の脱落や、繰り返しの測定による練習効果が問題となる。両者を組み合わせた系列法もある。","k":["横断研究","縦断研究","コホート","追跡","脱落","系列法"],"p":"修士研究では短期縦断（数か月の2時点調査）なども現実的な選択肢になる。"},{"id":"action-research","t":"アクションリサーチ","en":"action research","f":"kenkyu","a":"レヴィン（Lewin, K.）が提唱した研究法で、研究者が実践の場の当事者と協働しながら、問題を明らかにし、改善のための計画を立てて実践し、その結果を評価して次の計画に活かすという循環を繰り返すことで、社会的な問題の解決と知識の生成を同時にめざす。研究者が対象から距離をとる従来の研究に対し、現場の変化そのものに関わる点に特徴がある。学校や地域、組織における、コミュニティ心理学的な実践の研究などに用いられる。","k":["レヴィン/Lewin","当事者","協働","計画","循環","実践"],"p":"「研究者の中立性」をどう考えるか、という論点も添えられると厚みが出る。"},{"id":"ethics-research","t":"研究倫理","en":"research ethics","f":"kenkyu","a":"研究の参加者の人権と福祉を守るために、研究者が守るべき倫理的な原則と手続きをいう。研究の目的や方法、予想される負担やリスク、参加が自由意思によること、いつでも不利益なく中止できること、個人情報の保護などを説明したうえで同意を得るインフォームド・コンセントが基本となる。研究計画は、事前に倫理審査委員会の審査を受ける。データの捏造、改ざん、盗用は研究不正として厳しく禁じられる。臨床研究では、研究への協力の有無が支援に影響しないよう配慮する。","k":["人権","インフォームド・コンセント","自由意思","倫理審査委員会","捏造","盗用"],"p":"研究計画書・口述試験の頻出論点。とくに「傷つきやすい対象者（被害体験のある人、子ども、患者）」を対象とする場合の配慮を具体的に書けるようにする。"},{"id":"replication","t":"再現性の危機","en":"replication crisis","f":"kenkyu","a":"過去に発表された心理学の研究の多くが、追試によって同じ結果を再現できないことが明らかになった問題をいう。2015年に発表された大規模な追試のプロジェクトでは、元の研究と同じく有意な結果が得られたのは半数を大きく下回った。その背景として、有意な結果ほど公表されやすい出版バイアスや、有意になるまで分析を繰り返すpハッキング、結果を見てから仮説を立てるHARKingなどの問題が指摘された。対策として、研究の事前登録やデータの公開などのオープンサイエンスの取り組みが進められている。","k":["追試","2015","出版バイアス","pハッキング","HARKing","事前登録"],"p":"研究計画書で「仮説を事前に明示する」ことの意義を説明する際の根拠になる。"},{"id":"ceiling","t":"天井効果と床効果","en":"ceiling / floor effect","f":"kenkyu","a":"天井効果とは、課題が易しすぎる、あるいは尺度の上限が低すぎるために、多くの参加者の得点が上限付近に集まり、それ以上の差や変化をとらえられなくなることをいう。床効果はその逆で、課題が難しすぎるなどの理由で、得点が下限付近に集まることをいう。いずれも得点の分布が偏り、群間の差や介入の効果を過小に評価したり、統計的な検定の前提を損なったりする。予備調査によって、課題の難易度や尺度の範囲を適切に設定することが求められる。","k":["易しすぎ","上限","床効果","下限","過小","予備調査"],"p":"臨床群と一般群で同じ尺度を使う場合などに起こりやすい、という具体例を添えるとよい。"},{"id":"anova","t":"分散分析と交互作用","en":"ANOVA / interaction","f":"kenkyu","a":"分散分析は、3つ以上の群の平均値の差や、複数の要因の効果を同時に検討する方法である。要因が2つ以上ある場合、それぞれの要因が単独で結果に与える影響を主効果、ある要因の効果が他の要因の水準によって異なることを交互作用という。たとえば、ある心理療法の効果が、症状の重い人では大きく、軽い人では小さい場合、治療と重症度の間に交互作用がある。交互作用が有意な場合には、主効果だけで解釈せず、単純主効果の検定などで詳しく検討する。","k":["3つ以上","平均","主効果","交互作用","水準","単純主効果"],"p":"t検定を繰り返すと第1種の誤りが増えるため分散分析を用いる、という理由づけも書けるように。"},{"id":"regression","t":"重回帰分析","en":"multiple regression analysis","f":"kenkyu","a":"一つの目的変数（従属変数）を、複数の説明変数（独立変数）の一次式で予測・説明する分析の方法。各説明変数の影響の大きさは、他の説明変数の影響を取り除いたうえでの値である偏回帰係数（標準化したものは標準偏回帰係数）で示され、モデル全体の説明力は決定係数（R²）で示される。説明変数どうしの相関が強すぎると係数の推定が不安定になる多重共線性に注意が必要である。また、回帰分析の結果は、それだけでは因果関係を示すものではない。","k":["目的変数/従属変数","説明変数/独立変数","偏回帰係数","決定係数","多重共線性","因果"],"p":"媒介分析・調整分析（交互作用項）へと発展させる研究計画も多い。用語の違いを整理しておく。"},{"id":"kouninshinrishi","t":"公認心理師法","en":"Certified Public Psychologist Act","f":"rinri","a":"2015年に成立し、2017年に施行された、心理職として初めての国家資格である公認心理師について定めた法律。公認心理師の業務として、心理に関する支援を要する者の心理状態の観察とその結果の分析、その者への相談・助言・指導などの援助、その関係者への援助、心の健康に関する知識の普及のための教育と情報の提供の4つを定める。義務として、信用失墜行為の禁止、秘密保持義務、多職種との連携と、支援の対象者に主治の医師がいる場合にはその指示を受けること、資質向上の責務などを規定している。","k":["2015","2017","国家資格","秘密保持","連携","主治の医師"],"p":"名称独占資格であって業務独占ではない点、臨床心理士（民間資格）との関係もあわせて説明できるようにしておく。"},{"id":"confidentiality","t":"秘密保持とその例外","en":"confidentiality and its limits","f":"rinri","a":"心理職は、職務上知り得たクライエントの秘密を守る義務を負い、これは信頼関係と心理支援の土台である。ただし、自傷他害のおそれがあるなど生命や安全に危険が迫っている場合、虐待が疑われ通告が義務とされる場合、法令にもとづく場合などは例外となりうる。アメリカのタラソフ判決（1976年）は、クライエントが特定の他者に危害を加える危険がある場合、治療者にはその人を保護する義務があるとした。例外がありうることは、あらかじめクライエントに説明しておくことが望ましい。","k":["秘密","信頼関係","自傷他害","虐待","タラソフ","説明"],"p":"「チーム内守秘（集団守秘義務）」の考え方と、本人の同意を得て関係者と情報共有する手続きを書けると事例問題に強い。"},{"id":"multiple-rel","t":"多重関係","en":"multiple relationships","f":"rinri","a":"心理職とクライエントとの間に、専門的な援助関係に加えて、友人、恋愛、金銭の取引、仕事上の関係など、別の関係が同時に、あるいは前後して存在することをいう。多重関係は、心理職の客観性を損ない、クライエントを利己的に利用したり搾取したりする危険を高めるため、原則として避けるべきとされる。とくに性的な関係は、いかなる場合も許されない。地域が限られている場合など避けがたい場合には、その影響を十分に検討し、スーパービジョンを受けることが求められる。","k":["クライエント","友人/恋愛","客観性","搾取","性的な関係","スーパービジョン"],"p":"贈り物を受け取るか、SNSでつながるか、など身近な境界の問題に置き換えて論じられるようにしておく。"},{"id":"informed-consent","t":"インフォームド・コンセント","en":"informed consent","f":"rinri","a":"支援を受ける人が、支援の目的、方法、期間、料金、期待される効果と限界、ありうるリスク、他の選択肢、秘密保持とその例外などについて十分な説明を受け、理解したうえで、自由意思にもとづいて同意することをいう。自己決定権の尊重を基盤とする。心理支援では、初回だけでなく、方針の変更時などにも必要に応じて繰り返し行う。子どもや判断能力に制約のある人の場合は、保護者の同意に加え、本人にも理解できる形で説明し、本人の賛意（アセント）を得ることが大切である。","k":["説明","理解","自由意思","自己決定","繰り返し","アセント"],"p":"「書類に署名をもらうこと」ではなく「対話のプロセス」であることを強調する。"},{"id":"supervision","t":"スーパービジョン","en":"supervision","f":"rinri","a":"経験を積んだ心理職（スーパーバイザー）が、より経験の浅い心理職（スーパーバイジー）の担当する事例について、継続的に指導や助言を行うことをいう。クライエントの理解と支援の質を高めてクライエントを守るとともに、スーパーバイジーの専門的な成長を支える教育的な機能をもつ。事例の見立てや介入だけでなく、治療者の逆転移や感情的な反応も検討の対象となる。個人で行うほか、グループで行う形もある。治療者自身が心理療法を受ける教育分析とは区別される。","k":["スーパーバイザー","継続","事例","成長","逆転移","教育分析"],"p":"口述試験で「大学院で何を学びたいか」を問われたときにも、実習とスーパービジョンの意義は語れるようにしておく。"},{"id":"community","t":"コミュニティ心理学","en":"community psychology","f":"rinri","a":"1965年にアメリカのボストン郊外で開かれたスワンプスコット会議を契機に成立した心理学の領域。問題の原因を個人の内面だけに求めるのではなく、人と環境の適合という観点から問題をとらえ、地域社会の中で人々の生活を支える仕組みづくりをめざす。キャプランの予防の考え方、危機介入、コンサルテーション、ソーシャル・サポートのネットワークづくり、エンパワメント、アウトリーチなどを重視し、専門家と地域住民との協働を大切にする。","k":["1965","スワンプスコット","環境","予防","コンサルテーション","エンパワメント"],"p":"「面接室の中の心理療法」との対比で、その意義と限界を論じさせる出題が考えられる。"},{"id":"prevention","t":"予防の3段階","en":"primary, secondary, tertiary prevention","f":"rinri","a":"精神科医のキャプラン（Caplan, G.）が、地域精神保健の考え方として示した予防の枠組み。一次予防は、心の問題の発生そのものを防ぐことで、心の健康教育やストレスへの対処の学習などがある。二次予防は、問題を早期に発見して早期に対応し、重症化や長期化を防ぐことで、スクリーニングや相談体制の整備などがある。三次予防は、すでに生じた問題による障害を最小限にし、再発を防いで社会復帰を支援することで、リハビリテーションなどがある。","k":["キャプラン/Caplan","一次予防","二次予防","三次予防","早期","再発"],"p":"学校・職場・地域など具体的な場面ごとに、3段階の取り組みの例を挙げられるようにしておく。"},{"id":"consultation","t":"コンサルテーション","en":"consultation","f":"rinri","a":"ある領域の専門家（コンサルタント）が、別の領域の専門家（コンサルティ）から、その人が担当している事例や業務上の課題について相談を受け、より効果的に対応できるよう援助する過程をいう。たとえば、スクールカウンセラーが教師の相談に応じることがこれにあたる。両者は対等な専門家どうしの関係にあり、事例への責任はコンサルティが負う。キャプランは、事例を中心とするか、コンサルティを中心とするかなどにより4つの型に分類した。","k":["コンサルタント","コンサルティ","教師","対等","責任","キャプラン"],"p":"スーパービジョン（上下関係・同職種・責任をスーパーバイザーも負う）との違いを表で整理しておく。"},{"id":"empowerment","t":"エンパワメント","en":"empowerment","f":"rinri","a":"社会的に不利な立場に置かれた人々や集団が、自分の生活や環境に影響を与える力をもっていることに気づき、その力を発揮して、自らの人生のあり方を主体的にコントロールできるようになる過程、またそれを支える援助をいう。コミュニティ心理学では、ラパポート（Rappaport, J.）がその重要性を論じた。専門家が一方的に問題を解決するのではなく、当事者がもつ強みや資源に注目し、当事者と協働しながら、個人、組織、地域の各水準で力を高めていくことを重視する。","k":["不利","力","主体","ラパポート/Rappaport","強み","協働"],"p":"被害者支援、障害者支援、自助グループなど、具体的な場面と結びつけて書くと説得力が増す。"},{"id":"rinshoshinrishi","t":"臨床心理士","en":"clinical psychologist (JSCCP)","f":"rinri","a":"日本臨床心理士資格認定協会が1988年から認定している心理職の資格。指定大学院（第1種・第2種）または専門職大学院を修了し、資格審査に合格する必要があり、5年ごとの資格更新の制度をもつ。業務として、臨床心理査定（アセスメント）、臨床心理面接、臨床心理的地域援助、およびそれらに関する調査・研究の4つが挙げられている。国家資格である公認心理師の誕生後も、高度な専門性を担保する資格として、多くの領域で両資格が並んで求められている。","k":["日本臨床心理士資格認定協会","1988","指定大学院","更新","臨床心理査定","臨床心理的地域援助"],"p":"口述試験で「なぜ両方の資格を目指すのか」と問われたときに、それぞれの特徴（国家資格・連携／大学院教育・研究と更新制）を説明できるように。"},{"id":"sp-model","t":"科学者－実践者モデル","en":"scientist-practitioner model","f":"rinri","a":"1949年にアメリカのボルダー会議で示された、臨床心理学の専門家を養成するためのモデル。臨床心理学者は、心理学の科学的な研究の訓練と、臨床実践の訓練の両方を受け、研究によって得られた知見を実践に活かすとともに、実践の中から研究の問いを見いだす存在であるべきだとする。エビデンスにもとづく実践の考え方にもつながっている。一方で、研究と実践の統合が実際には難しいという批判もあり、実践を重視する実践者－学者モデルなども提唱された。","k":["1949","ボルダー","研究","実践","統合","エビデンス"],"p":"大学院で研究と実習の両方を学ぶ意味（修士論文を書く意義）を語る口述試験の質問にも使える。"},{"id":"ebp","t":"エビデンス・ベイスト・プラクティス","en":"evidence-based practice","f":"rinri","a":"心理支援において、①利用可能な最善の研究成果（エビデンス）を、②臨床家の専門的な技能や判断と統合し、③クライエントの特性、文化、価値観、希望を考慮して、支援の方針を決定することをいう（アメリカ心理学会、2006年）。エビデンスを機械的に当てはめるのではなく、目の前のクライエントにとって最善の支援を選ぶための考え方である。エビデンスの階層では、一般に、RCTのシステマティック・レビューやメタ分析が上位に置かれる。","k":["エビデンス","臨床家","統合","価値観/希望","アメリカ心理学会/APA","メタ分析"],"p":"「マニュアル的な治療」と誤解されやすい。3つの要素の「統合」であることを必ず書く。"},{"id":"suicide","t":"自殺の危機への対応","en":"suicide risk and response","f":"rinri","a":"自殺の危険因子には、過去の自殺企図、精神疾患、喪失体験、孤立、援助を求めにくいことなどがあり、保護因子には、周囲とのつながりや支援への信頼などがある。自殺をほのめかす人には、話題を避けず、自殺について率直に尋ねることが勧められ、尋ねることが自殺の危険を高めるわけではない。TALKの原則（Tell：心配していると伝える、Ask：死にたい気持ちについて尋ねる、Listen：傾聴する、Keep safe：安全を確保する）が知られる。一人で抱え込まず、関係者と連携することが重要である。","k":["危険因子","自殺企図","孤立","尋ね","TALK","連携"],"p":"秘密保持の例外とセットで出題されやすい。「本人との関係を保ちながら安全を確保する」両立のしかたを書く。"},{"id":"mhw-law","t":"精神保健福祉法","en":"Mental Health and Welfare Act","f":"rinri","a":"精神保健福祉法は、精神障害者の医療と保護、社会復帰の促進、自立と社会参加の促進のための援助などを定めた法律である。入院の形態として、本人の同意にもとづく任意入院、精神保健指定医の診察により医療と保護のために入院が必要だが本人の同意が得られない場合に家族等の同意で行う医療保護入院、自傷他害のおそれがある場合に都道府県知事の権限で行う措置入院、急を要する場合の緊急措置入院や応急入院がある。本人の人権への配慮が強く求められる。","k":["任意入院","精神保健指定医","医療保護入院","家族等","措置入院","自傷他害"],"p":"非自発的な入院が本人の自己決定とどう緊張関係にあるか、という倫理的な論点として出題されうる。"},{"id":"reasonable-acc","t":"合理的配慮","en":"reasonable accommodation","f":"rinri","a":"障害のある人が、障害のない人と平等に権利を行使し、社会に参加できるよう、個々の状況に応じて行われる必要かつ適当な変更や調整のうち、行う側にとって過重な負担とならないものをいう。障害者権利条約で示され、日本では障害者差別解消法により、行政機関に加え、2024年4月からは民間の事業者にも提供が義務づけられた。障害を個人の問題ではなく、社会の障壁との相互作用で生じるものとみる社会モデルの考えにもとづき、本人との対話を通じて調整していく。","k":["平等","過重な負担","障害者権利条約","障害者差別解消法","2024","社会モデル"],"p":"心理職の役割（本人の特性の理解を助け、必要な配慮を一緒に言語化する）を書けると実践的。"},{"id":"four-care","t":"職場のメンタルヘルスの4つのケア","en":"four types of care at work","f":"rinri","a":"厚生労働省の「労働者の心の健康の保持増進のための指針」が示す、職場におけるメンタルヘルス対策の枠組み。労働者自身がストレスに気づき対処するセルフケア、管理監督者が職場環境の改善や部下の相談への対応を行うラインによるケア、産業医や保健師、心理職などの産業保健スタッフ等によるケア、外部の医療機関や相談機関などを活用する事業場外資源によるケアの4つからなる。これらを継続的かつ計画的に行うことが求められ、心理職は職場復帰の支援などにも関わる。","k":["厚生労働省","セルフケア","ラインによるケア","産業保健スタッフ","事業場外資源","職場復帰"],"p":"休職・復職の事例問題で、本人・上司・産業医・主治医の連携を整理する枠組みとして使える。"},{"id":"ethics-7","t":"職業倫理の7原則","en":"seven principles of professional ethics","f":"rinri","a":"金沢吉展が整理した、心理職の職業倫理の基本原則。①相手を傷つけない、傷つけるようなおそれのあることをしない、②十分な教育と訓練によって身につけた専門的な行動の範囲内で、相手の健康と福祉に寄与する、③相手を利己的に利用しない、④一人ひとりを人間として尊重する、⑤秘密を守る、⑥インフォームド・コンセントを得て、相手の自己決定権を尊重する、⑦すべての人々を公平に扱い、社会的な正義と公正・平等の精神を具現する、の7つからなる。","k":["金沢吉展","傷つけない","利己的","秘密","インフォームド・コンセント","公平"],"p":"倫理の事例問題では、どの原則とどの原則が衝突しているか（例：秘密保持と安全の確保）を示すと論理的な答案になる。"},{"id":"burnout","t":"バーンアウト","en":"burnout","f":"rinri","a":"対人援助職などにみられる、長期にわたる過度の心理的な負担によって、心身のエネルギーが枯渇した状態をいい、燃え尽き症候群とも呼ばれる。マスラック（Maslach, C.）は、情緒的消耗感、相手を人として扱わなくなる脱人格化、仕事の成果が感じられなくなる個人的達成感の低下の3つの側面からとらえ、その測定尺度を作成した。熱意をもって仕事に取り組む人ほど陥りやすいとされる。個人のセルフケアだけでなく、職場の業務量や支え合いの体制など、組織としての対策が重要である。","k":["対人援助","マスラック/Maslach","情緒的消耗感","脱人格化","個人的達成感","組織"],"p":"代理受傷・共感疲労（トラウマの内容に由来）との違い（業務負担一般に由来）を書き分ける。"},{"id":"multicultural","t":"多文化と文化的コンピテンス","en":"multicultural competence","f":"rinri","a":"心理支援が、クライエントと支援者それぞれの文化的な背景（民族、言語、宗教、ジェンダー、性的指向、障害、社会階層など）の影響を受けることを踏まえ、文化的な多様性に配慮した支援を行う能力をいう。スー（Sue, D. W.）らは、支援者自身の文化的な価値観や偏見への自覚、クライエントの文化についての知識、文化に適した介入の技能の3つを挙げた。支援者の文化の基準でクライエントを病理化しないことが重要であり、マイクロアグレッションへの感受性も求められる。","k":["文化","多様性","スー/Sue","自覚","知識","技能"],"p":"上智大学は国際性を重視する大学でもあり、外国にルーツをもつ人への支援などを口述試験で語れるようにしておくのも一案。"}]);
